const path = require('path');
require('dotenv').config({ path: path.resolve(__dirname, '..', '.env') });
const mongoose = require('mongoose');

const SCHOOL_ID = new mongoose.Types.ObjectId('69ce960a98ca4ee738d25416');
const CREATED_BY = new mongoose.Types.ObjectId('69ce960b98ca4ee738d25432');

let blockNum = 0;
function bid() { return 'block-' + String(++blockNum).padStart(3, '0'); }

function t(order, content) {
  return { blockId: bid(), type: 'text', order, content, points: 0, hints: [], explanation: '', metadata: {}, curriculumNodeId: null, cognitiveLevel: null };
}
function q(order, question, options, correctIndex, explanation, hints) {
  return {
    blockId: bid(), type: 'quiz', order,
    content: JSON.stringify({ question, options, correctIndex }),
    points: 1, hints: hints || [], explanation: explanation || '',
    metadata: { options, correctIndex }, curriculumNodeId: null, cognitiveLevel: null,
  };
}
function fb(order, text, blanks, explanation, hints) {
  return {
    blockId: bid(), type: 'fill_blank', order,
    content: JSON.stringify({ text, blanks }),
    points: blanks.length, hints: hints || [], explanation: explanation || '',
    metadata: { blanks }, curriculumNodeId: null, cognitiveLevel: null,
  };
}

// =============================================================================
// CHAPTER 1 (History – Term 1): The Kingdom of Mali and the City of Timbuktu
// Focus: The development of a rich economy and a learning centre of the
// kingdom of Mali long ago (14th Century)
// =============================================================================

// --- Lesson 1: Trade Across the Sahara and the Kingdom of Mali ---
blockNum = 0;
const ch1_lesson1 = [
  t(1, '## Trade Across the Sahara Desert\n\nLong before Europeans arrived in West Africa, a vast network of trade routes stretched across the **Sahara Desert**, connecting North Africa to the kingdoms of West Africa.\n\n### What Was Traded?\n\nGoods moved in both directions across the desert:\n\n| From North Africa to West Africa | From West Africa to North Africa |\n|----------------------------------|----------------------------------|\n| **Salt** (essential for preserving food and health) | **Gold** (West Africa was the world\'s biggest gold producer) |\n| Cloth and textiles | Ivory (elephant tusks) |\n| Horses | Kola nuts |\n| Books and manuscripts | Ostrich feathers |\n| Copper and metalware | Enslaved people |\n| Dates and dried fruit | Hides and leather |\n\n### Why Was Salt So Valuable?\n\n- In the hot climate of West Africa, people needed salt to replace what they lost through sweat\n- Salt was used to **preserve meat and fish** — essential before refrigeration existed\n- In some places, salt was as valuable as gold — traders exchanged equal weights of salt and gold\n- Major salt mines at **Taghaza** in the Sahara produced blocks of salt carried south by camel caravans\n\n### The Camel — "Ship of the Desert"\n\n- **Camels** made trans-Saharan trade possible because they could travel long distances without water\n- A camel caravan could include **1 000 to 12 000 camels**\n- The journey across the Sahara took about **two months**\n- Caravans followed established routes between **oases** (water sources in the desert)'),
  q(2, 'Why was salt so valuable in West Africa?',
    ['People needed salt to stay healthy in the hot climate, and salt was essential for preserving food', 'Salt was used to make jewellery', 'Salt was a type of currency used to pay taxes', 'Salt was only used by kings and was very rare worldwide'], 0,
    'In the hot climate of West Africa, people lost salt through sweating and needed to replace it. Salt was also the only way to preserve meat and fish in a time before refrigeration, making it as precious as gold in many West African markets.'),
  t(3, '## The Kingdom of Mali\n\nThe **Kingdom of Mali** was one of the largest and most powerful empires in African history. It existed from about **1235 to 1600** and covered a vast area of West Africa.\n\n### Origins of Mali\n\n- Mali grew out of the earlier **Ghana Empire** (not the same as modern Ghana)\n- The kingdom was founded by **Sundiata Keita** around **1235** after he defeated the Sosso king, Sumanguru Kante, at the Battle of Kirina\n- Sundiata united several small states into a powerful empire\n- The people of Mali were mostly **Mandinka** (also called Mande)\n\n### Mali at Its Height (14th Century)\n\n| Feature | Detail |\n|---------|--------|\n| **Size** | Stretched from the Atlantic coast to beyond the Niger River — roughly the size of Western Europe |\n| **Capital** | Niani (on the upper Niger River) |\n| **Population** | Estimated at 40-50 million people |\n| **Wealth** | Controlled the gold and salt trade routes |\n| **Language** | Mandinka |\n| **Religion** | Islam (adopted by rulers, alongside traditional beliefs) |\n| **Government** | Centralised rule by the Mansa (emperor) with provincial governors |\n\n### Sources of Wealth\n\n- Mali controlled the **gold mines** of Wangara (Bambuk and Bure regions)\n- It controlled the **salt trade** from the Sahara\n- **Taxes** were collected on all goods passing through the empire\n- Agriculture along the fertile **Niger River** fed the population'),
  fb(4, 'The Kingdom of Mali was founded by ___ Keita around 1235. At its height, Mali controlled both the gold and ___ trade routes across the Sahara.',
    ['Sundiata', 'salt'],
    'Sundiata Keita is considered the founder and first Mansa (emperor) of Mali. His control over both the gold-producing regions and the salt trade routes made Mali one of the wealthiest empires in the world during the 14th century.'),
  t(5, '## Mansa Musa — The Richest Man in History\n\n**Mansa Musa** (ruled 1312-1337) is considered the **wealthiest person who has ever lived**. His rule marked the golden age of the Mali Empire.\n\n### Mansa Musa\'s Pilgrimage to Mecca (1324-1325)\n\nAs a devout Muslim, Mansa Musa undertook the **hajj** (pilgrimage) to Mecca in 1324. This journey made Mali famous across the world.\n\n| Aspect | Detail |\n|--------|--------|\n| **Entourage** | 60 000 people, including 12 000 servants |\n| **Gold** | 80 camels each carried 136 kg of gold dust |\n| **Route** | Across the Sahara, through Egypt, to Mecca |\n| **Impact in Cairo** | He gave away so much gold that the price of gold crashed and did not recover for 12 years |\n| **Duration** | The round trip took about two years |\n\n### Mansa Musa\'s Achievements\n\n- Made Mali known throughout the Islamic world and Europe\n- Built the **Djinguereber Mosque** in Timbuktu (still standing today)\n- Brought scholars, architects, and books back from his pilgrimage\n- Established Timbuktu as a centre of **Islamic learning**\n- Mali appeared on European maps — the 1375 **Catalan Atlas** showed Mansa Musa holding a gold nugget\n\n### Government Under Mansa Musa\n\n- The empire was divided into **provinces**, each governed by a **farba** (governor)\n- Laws and justice were administered fairly — the Arab traveller Ibn Battuta praised the safety of Mali\n- Trade was encouraged through **stable governance** and protection of trade routes'),
  q(6, 'What happened when Mansa Musa passed through Cairo on his way to Mecca?',
    ['He gave away so much gold that the price of gold crashed in Cairo and did not recover for 12 years', 'He conquered Cairo and made it part of Mali', 'He traded salt for Egyptian cotton', 'Nothing notable happened during his visit'], 0,
    'Mansa Musa\'s generosity in Cairo was so extraordinary that he flooded the local economy with gold. The sudden increase in the supply of gold caused its value to drop dramatically, showing just how wealthy the Mali Empire was.'),
  t(7, '## The Spread of Islam in West Africa\n\nIslam played a major role in shaping the Kingdom of Mali and its connections to the wider world.\n\n### How Islam Spread\n\n- Islam was brought to West Africa by **Arab and Berber traders** who crossed the Sahara\n- Trade and religion were closely linked — Muslim traders preferred to do business with fellow Muslims\n- Mali\'s rulers adopted Islam because it:\n  - Connected them to the wider **Islamic world** and trade networks\n  - Provided a system of **laws** (Sharia) that helped govern the empire\n  - Gave them **literacy** through the Arabic script\n  - Brought **prestige** and diplomatic connections\n\n### Islam and Traditional Beliefs\n\n- Many people in Mali practised a **blend** of Islam and traditional African religions\n- Rulers were Muslim, but ordinary people often kept their traditional beliefs\n- This blending of religions is called **syncretism**\n- Traditional beliefs included ancestor worship, nature spirits, and oral traditions\n\n### The Role of Scholars\n\n- Islamic scholars were highly respected in Mali\n- They served as **advisers** to the Mansa, as **judges** (qadis), and as **teachers**\n- The Arabic script allowed Mali to keep **written records** of laws, trade, and history\n- Scholars from across the Islamic world were attracted to Mali\'s wealth and learning'),
  fb(8, 'Islam was brought to West Africa by Arab and ___ traders who crossed the Sahara. The blending of Islam with traditional African religions is called ___.',
    ['Berber', 'syncretism'],
    'Berber traders from North Africa were among the first to bring Islam south across the Sahara. Syncretism — the blending of different religious practices — was common throughout West Africa. Many people combined Islamic worship with traditional beliefs about ancestors and nature spirits.'),
  q(9, 'Why did Mali\'s rulers adopt Islam?',
    ['It connected them to wealthy Islamic trade networks, provided written laws, gave them literacy, and brought diplomatic prestige', 'They were forced to convert by invading armies', 'Islam was the only religion in West Africa', 'They wanted to stop trading with North Africa'], 0,
    'Adopting Islam was a strategic choice. It connected Mali\'s rulers to the vast Islamic trading world stretching from Spain to China. Islamic law provided a framework for governing a large empire, and Arabic literacy allowed record-keeping and diplomacy.'),
  t(10, '## Transport Through Time\n\nThe CAPS curriculum connects the study of Mali to the broader topic of **transport through history**.\n\n### Transport on Land\n\n| Period | Transport Method |\n|--------|------------------|\n| **Earliest times** | Walking; carrying goods on heads or backs |\n| **Domestication of animals** | Donkeys, horses, oxen used to carry loads |\n| **The camel** | Revolutionised Saharan trade — could travel days without water |\n| **Wheeled vehicles** | Carts and wagons pulled by animals |\n| **The railway (1800s)** | Steam-powered trains transformed land transport |\n| **Motor vehicles (1900s)** | Cars, trucks, and buses |\n\n### Camel Caravans Across the Sahara\n\n- Camel caravans were the **backbone of trans-Saharan trade** for over 1 000 years\n- Camels can carry up to **200 kg** and travel **40 km per day**\n- They can go up to **seven days without water**\n- Caravans stopped at **oases** for water and rest\n- The journey from Timbuktu to Morocco took about **two months**\n\n### Grade 4 Revision: Transport\n\nRemember from Grade 4:\n- Transport on land has evolved from walking to high-speed trains\n- Animals (donkeys, horses, camels) were crucial before engines were invented\n- Carts and wagons were used for carrying heavy loads\n- Each new form of transport made trade easier, faster, and more profitable'),
];

// --- Lesson 2: The City of Timbuktu ---
blockNum = 0;
const ch1_lesson2 = [
  t(1, '## Timbuktu as a Trade Centre\n\nThe city of **Timbuktu** was founded around **1100** as a seasonal camp for Tuareg nomads near the Niger River. By the 14th century, it had become one of the most important cities in the world.\n\n### Location and Importance\n\n- Timbuktu sits at the edge of the **Sahara Desert**, where it meets the fertile **Niger River** floodplain\n- This location made it the perfect **meeting point** for traders from North Africa and West Africa\n- Goods from the Sahara (salt) met goods from the south (gold, kola nuts, ivory)\n- The Niger River provided **water transport** as well as fresh water and fertile farmland\n\n### The Trans-Saharan Caravan Route\n\n| Stage | Route |\n|-------|-------|\n| **Start** | Salt mines at Taghaza (deep in the Sahara) |\n| **Across the desert** | Two months by camel caravan through harsh desert |\n| **Arrival** | Timbuktu — the great trading city |\n| **Further south** | Goods moved by boat along the Niger River or overland to gold-producing regions |\n\n### What Traders Found in Timbuktu\n\n- A bustling city of perhaps **100 000 people** at its height\n- Markets selling goods from across Africa, the Middle East, and Europe\n- Different peoples — Tuareg, Mandinka, Songhai, Arabs, Berbers — trading peacefully\n- A well-governed city with laws, police, and regulated trade'),
  q(2, 'Why was Timbuktu\'s location ideal for trade?',
    ['It was at the meeting point of the Sahara Desert and the Niger River, connecting North African and West African trade routes', 'It was on the coast and had a natural harbour', 'It was in the centre of a gold mine', 'It was built on top of a salt deposit'], 0,
    'Timbuktu\'s position on the southern edge of the Sahara and near the Niger River made it the natural meeting point for traders from both directions. Salt and goods from the north met gold and products from the south, making Timbuktu one of the greatest trading cities in history.'),
  t(3, '## Leo Africanus\' Description of Timbuktu\n\n**Leo Africanus** (al-Hasan ibn Muhammad al-Wazzan) was a Moroccan traveller and scholar who visited Timbuktu around **1510-1512**. His book, *Description of Africa* (1550), gave Europeans their first detailed account of the city.\n\n### What Leo Africanus Wrote\n\n- The king of Timbuktu was very wealthy and had **many plates and sceptres of gold**\n- The city had a **great store of doctors, judges, priests, and other learned men**\n- Books and manuscripts were the **most profitable trade goods** — more valuable than any other merchandise\n- There were many shops and the city was well supplied with food\n- Justice was strictly administered and the people were **honest and peace-loving**\n\n### Significance of His Account\n\n- Leo Africanus\' writings were translated into many European languages\n- They made Europeans **aware** of the wealth and sophistication of West African civilisations\n- However, many Europeans refused to believe that Africans could build such advanced cities\n- His description challenged the racist myth that Africa had no history or civilisation\n\n### Using Sources Critically\n\nHistorians must consider:\n- Leo Africanus visited **after** Timbuktu\'s peak — the city was already declining\n- His account was written from **memory**, years after his visit\n- He wrote in Italian for a European audience, which may have influenced what he included\n- Despite these limitations, his description is one of the most valuable sources on Timbuktu'),
  fb(4, 'Leo ___ was a Moroccan traveller who wrote a detailed description of Timbuktu around 1510-1512. He noted that ___ and manuscripts were the most profitable trade goods in the city.',
    ['Africanus', 'books'],
    'Leo Africanus\' account revealed that Timbuktu was a centre of learning where books were more valued than any other commodity. This contradicted European assumptions about Africa and remains one of our most important sources about medieval West Africa.'),
  t(5, '## Timbuktu as a Centre of Learning\n\nTimbuktu was not just a trading city — it was one of the **greatest centres of learning** in the medieval world.\n\n### The University of Sankore\n\n- The **Sankore Mosque** (also called the University of Sankore) was a major centre of Islamic scholarship\n- At its peak, Timbuktu had **three great mosques**: Djinguereber, Sankore, and Sidi Yahia\n- The university attracted scholars from across the Islamic world\n- It had up to **25 000 students** at its height\n\n### What Was Studied?\n\n| Subject | Details |\n|---------|----------|\n| **Islamic theology** | Study of the Quran and Islamic law |\n| **Mathematics** | Arithmetic, geometry, and algebra |\n| **Astronomy** | Study of stars and planets; predicting seasons |\n| **Medicine** | Herbal remedies and surgical techniques |\n| **History** | Recording and studying the past |\n| **Geography** | Knowledge of lands, peoples, and trade routes |\n| **Law** | Islamic jurisprudence and legal interpretation |\n| **Chemistry/optics/physics** | Scientific knowledge from the Islamic world |\n\n### The Manuscripts of Timbuktu\n\n- Scholars in Timbuktu produced and collected **hundreds of thousands** of manuscripts\n- These were handwritten in Arabic and in local languages using Arabic script\n- Topics included science, law, history, poetry, medicine, and philosophy\n- Many manuscripts have survived and are being **preserved** today by organisations like the Timbuktu Manuscripts Project'),
  q(6, 'What subjects were studied at the University of Sankore in Timbuktu?',
    ['A wide range including Islamic theology, mathematics, astronomy, medicine, history, geography, and law', 'Only religious studies were taught', 'Only trade and commerce were studied', 'No formal education existed in Timbuktu'], 0,
    'The University of Sankore offered a remarkably broad curriculum that rivalled any European university of the time. Scholars studied everything from astronomy and mathematics to medicine and law, showing that Timbuktu was a world-class centre of intellectual achievement.'),
  t(7, '## Timbuktu Manuscripts — A South African Connection\n\n### The Manuscripts\n\n- An estimated **700 000 manuscripts** survive from Timbuktu and the surrounding region\n- They cover topics from astronomy to music, from law to love poetry\n- Many were hidden in private family libraries for centuries, protected from invaders\n- Some are over **800 years old**\n\n### The South African–Mali Manuscripts Project\n\n- In **2003**, South Africa and Mali signed an agreement to preserve Timbuktu\'s manuscripts\n- The **Timbuktu Manuscripts Project** was launched by the then-president of South Africa, **Thabo Mbeki**\n- South Africa helped build libraries and conservation centres in Timbuktu\n- This project is an example of **African collaboration** — two African countries working together to preserve shared heritage\n\n### Why Timbuktu Is a World Heritage Site\n\nTimbuktu was declared a **UNESCO World Heritage Site** in 1988 because:\n- It was one of the greatest intellectual and spiritual centres in Africa\n- The three great mosques (Djinguereber, Sankore, Sidi Yahia) are architectural treasures\n- The manuscripts represent an irreplaceable record of African and Islamic scholarship\n- It demonstrates that Africa had sophisticated civilisations and centres of learning centuries before European colonisation'),
  fb(8, 'An estimated ___ manuscripts survive from Timbuktu and the surrounding region. South Africa and Mali launched a joint project to preserve these manuscripts in ___.',
    ['700 000', '2003'],
    'The Timbuktu manuscripts are among the most important historical records in Africa. The South African–Mali partnership to preserve them is an example of pan-African cooperation and recognition that Africa\'s intellectual heritage belongs to all Africans.'),
  q(9, 'Why is Timbuktu\'s intellectual heritage important for challenging stereotypes about Africa?',
    ['It proves that Africa had sophisticated centres of learning, scholarship, and science centuries before European colonisation', 'It shows that Africa had no history worth studying', 'Europeans built the universities in Timbuktu', 'Timbuktu was only important for trade, not learning'], 0,
    'Timbuktu\'s manuscripts, universities, and scholarly traditions directly challenge the racist colonial myth that Africa had no history, science, or civilisation. The fact that Timbuktu had 25 000 students studying advanced subjects in the 1400s shows the depth of African intellectual achievement.'),
  t(10, '## The Decline of the Mali Empire and Timbuktu\n\n### Why Did Mali Decline?\n\n| Factor | Explanation |\n|--------|-------------|\n| **Weak rulers** | After Mansa Musa, some later rulers were less capable |\n| **Succession disputes** | Conflict over who should be Mansa weakened central authority |\n| **Provincial rebellions** | Outlying provinces broke away from Mali\'s control |\n| **Rise of Songhai** | The Songhai Empire, based at Gao, conquered Timbuktu in 1468 |\n| **Moroccan invasion (1591)** | Moroccan soldiers with **guns** (firearms) defeated the Songhai army and took Timbuktu |\n| **Disrupted trade** | Political instability disrupted the trans-Saharan trade routes |\n\n### The Songhai Empire\n\n- The **Songhai Empire** replaced Mali as the dominant power in the region\n- Under **Sunni Ali** (ruled 1464-1492) and **Askia Muhammad** (ruled 1493-1528), Songhai expanded greatly\n- Timbuktu continued to flourish as a centre of learning under Songhai rule\n- The Songhai Empire fell when **Morocco invaded in 1591**, using firearms against soldiers armed with swords and spears\n\n### Legacy of Mali and Timbuktu\n\n- Mali demonstrated that **African civilisations were advanced, wealthy, and sophisticated**\n- Timbuktu\'s scholarly tradition shows Africa\'s contribution to **world knowledge**\n- The trans-Saharan trade routes connected Africa to the global economy centuries before European colonisation\n- The surviving manuscripts are a treasure that continues to be studied and preserved today'),
];

// =============================================================================
// CHAPTER 2 (Geography – Term 1): Map Skills — Focus: The World
// =============================================================================

// --- Lesson 1: Maps, Scales, and Compass Directions ---
blockNum = 0;
const ch2_lesson1 = [
  t(1, '## Introduction to Map Skills\n\nMaps are one of the most important tools in Geography. In Grade 7, we build on the map skills learned in earlier grades by working with **world maps** and more detailed skills.\n\n### What Is a Map?\n\n- A map is a **flat representation** of all or part of the Earth\'s surface\n- Maps show features from a **bird\'s-eye view** (looking down from above)\n- Every map uses **symbols**, **colours**, and **labels** to represent real-world features\n\n### Kinds of Maps\n\n| Map Type | Purpose | Example |\n|----------|---------|----------|\n| **Political map** | Shows country borders and capitals | Map of Africa showing 54 countries |\n| **Physical map** | Shows landforms — mountains, rivers, deserts | Map showing the Himalayas and Sahara |\n| **Climate map** | Shows rainfall and temperature patterns | Map showing world climate zones |\n| **Population map** | Shows where people live and population density | Map showing densely populated areas |\n| **Economic/resource map** | Shows natural resources and industries | Map showing gold and diamond deposits |\n| **Topographic map** | Shows detailed natural and human features using contour lines and symbols | 1:50 000 maps used in South Africa |\n\n### Atlases\n\nAn **atlas** is a book of maps. A good atlas contains:\n- Political maps (showing borders)\n- Physical maps (showing landforms)\n- Thematic maps (showing specific data like climate, population, or resources)\n- An **index** to help find places\n- **Latitude and longitude** coordinates for locating places'),
  q(2, 'What is the difference between a political map and a physical map?',
    ['A political map shows country borders and capitals, while a physical map shows natural features like mountains and rivers', 'A political map shows weather patterns', 'A physical map shows population data', 'There is no difference between them'], 0,
    'Political maps focus on human-created boundaries — country borders, provinces, and capital cities. Physical maps show natural features — mountains, rivers, deserts, and oceans. Both types appear in atlases and are used for different purposes.'),
  t(3, '## Map Scale\n\nScale tells us the relationship between distances on a map and actual distances on the ground.\n\n### Types of Scale\n\n| Scale Type | Example | How It Works |\n|------------|---------|---------------|\n| **Word scale** | "1 cm represents 50 km" | Written in words — easy to understand |\n| **Number (ratio) scale** | 1:50 000 | 1 unit on the map equals 50 000 of the same units on the ground |\n| **Line (bar) scale** | A drawn bar with distances marked | A visual scale — still accurate if the map is enlarged or reduced |\n\n### Calculating Distance Using a Number Scale\n\n**Example:** On a 1:50 000 map, two towns are 6 cm apart. What is the actual distance?\n\n1. Map distance = 6 cm\n2. Multiply by scale: 6 × 50 000 = 300 000 cm\n3. Convert to km: 300 000 ÷ 100 000 = **3 km**\n\n### Conversion Reminder\n\n| To convert | Divide by |\n|------------|----------|\n| cm → m | 100 |\n| m → km | 1 000 |\n| cm → km | 100 000 |\n\n### Large-Scale vs Small-Scale Maps\n\n- **Large-scale map** (e.g., 1:10 000): Shows a **small area** with **lots of detail** — like a street map\n- **Small-scale map** (e.g., 1:1 000 000): Shows a **large area** with **less detail** — like a map of Africa\n\n**Memory trick:** Large scale = Large detail, Small area'),
  fb(4, 'On a 1:50 000 map, 1 cm on the map equals ___ cm (or 500 m) on the ground. A line scale remains accurate even if the map is ___ or reduced.',
    ['50 000', 'enlarged'],
    'At 1:50 000 scale, every centimetre on the map represents 50 000 cm on the ground, which equals 500 m. The line (bar) scale is the most reliable because it changes size proportionally when a map is photocopied or resized.'),
  t(5, '## Compass Directions\n\nA compass shows direction. Knowing compass directions is essential for reading maps and describing where places are in relation to each other.\n\n### The Eight Compass Points\n\n| Direction | Abbreviation | Position |\n|-----------|-------------|----------|\n| **North** | N | Top of the map |\n| **South** | S | Bottom of the map |\n| **East** | E | Right side of the map |\n| **West** | W | Left side of the map |\n| **North-East** | NE | Between North and East |\n| **North-West** | NW | Between North and West |\n| **South-East** | SE | Between South and East |\n| **South-West** | SW | Between South and West |\n\n### Compass Bearings\n\n- A **bearing** measures direction in degrees from North, measured clockwise\n- North = **0°** (or 360°)\n- East = **90°**\n- South = **180°**\n- West = **270°**\n- Bearings are always written as **three figures**: 045°, 090°, 180°, 270°\n\n### Determining Direction on a Map\n\n1. Find the **north arrow** on the map (it is usually at the top)\n2. Place your finger on the starting point\n3. Determine which compass direction leads to the destination\n4. For a bearing: use a **protractor** — place the centre on the starting point with 0° pointing north'),
  q(6, 'If a place is to the right and slightly up from your position on a map, in which compass direction is it?',
    ['North-East (NE)', 'South-West (SW)', 'North-West (NW)', 'South-East (SE)'], 0,
    'On a standard map, north is at the top and east is on the right. If a place is to the right (east) and slightly up (north), it is in the north-east direction. Understanding compass directions helps us describe the relative positions of places.'),
  t(7, '## Latitude and Longitude\n\nLatitude and longitude are an imaginary grid of lines on the Earth\'s surface that allow us to locate any place precisely.\n\n### Latitude\n\n- Lines of latitude run **east to west** (horizontally)\n- They measure how far **north or south** a place is from the **Equator** (0°)\n- Latitude ranges from **0°** (Equator) to **90°N** (North Pole) and **90°S** (South Pole)\n- Lines of latitude are also called **parallels** because they are always the same distance apart\n- Important lines: Tropic of Cancer (23.5°N), Tropic of Capricorn (23.5°S), Arctic Circle (66.5°N), Antarctic Circle (66.5°S)\n\n### Longitude\n\n- Lines of longitude run **north to south** (vertically)\n- They measure how far **east or west** a place is from the **Prime Meridian** (0°)\n- Longitude ranges from **0°** to **180°E** and **180°W**\n- Lines of longitude are called **meridians**\n- The Prime Meridian passes through **Greenwich**, London\n- The **International Date Line** is at approximately 180°\n\n### Coordinates\n\nEvery place on Earth has a unique set of coordinates:\n- **Latitude** is always written first: e.g., Cape Town is at **34°S, 18°E**\n- Coordinates can include **degrees, minutes, and seconds**: 33°55\'S, 18°25\'E'),
  fb(8, 'Lines of latitude are also called ___. The line of 0° longitude, which passes through Greenwich, London, is called the ___ Meridian.',
    ['parallels', 'Prime'],
    'Parallels of latitude are always the same distance apart and never meet. The Prime Meridian (0° longitude) divides the Earth into the Eastern and Western Hemispheres, just as the Equator divides it into the Northern and Southern Hemispheres.'),
  q(9, 'South Africa lies between approximately 22°S and 35°S latitude. In which hemisphere is South Africa located?',
    ['The Southern Hemisphere (south of the Equator)', 'The Northern Hemisphere', 'The Western Hemisphere', 'South Africa is on the Equator'], 0,
    'Any place with a latitude ending in "S" (south) is in the Southern Hemisphere — below the Equator. South Africa lies entirely in the Southern Hemisphere, between about 22°S (Limpopo border) and 35°S (Cape Agulhas, the southernmost point of Africa).'),
  t(10, '## Sketch Maps and Using a Local Map\n\nA **sketch map** is a simple, hand-drawn map that shows the basic layout of an area without precise scale or detail.\n\n### Features of a Good Sketch Map\n\nEvery sketch map must include:\n1. **Title** — what the map shows\n2. **North arrow** — showing the direction of north\n3. **Key (legend)** — explaining the symbols used\n4. **Labels** — naming important features\n5. **Frame (border)** — a neat border around the map\n\n### How to Draw a Sketch Map\n\n1. Decide what area you want to show\n2. Draw a frame (border)\n3. Mark the north arrow (usually pointing up)\n4. Sketch the main features: roads, buildings, rivers, landmarks\n5. Use simple symbols and label them in the key\n6. Add a title\n\n### Street Maps and Local Maps\n\n- **Street maps** show roads, buildings, and landmarks in a town or neighbourhood\n- They use a **grid reference system** (letters and numbers) to locate features\n- Example: "The school is at grid reference B3" means column B, row 3\n- Google Maps is a digital street map that most people use daily\n\n### Practical Activity\n\nUsing a street map (or Google Maps), you should be able to:\n- Identify roads and route directions\n- Use grid references to locate features\n- Give directions from one point to another using compass directions\n- Estimate distances using the map scale'),
];

// --- Lesson 2: Sketching Maps and Explaining Routes ---
blockNum = 0;
const ch2_lesson2 = [
  t(1, '## Drawing a Map of a Local Area\n\nIn this lesson, we practise the important skill of drawing accurate maps and using them to explain routes.\n\n### The Purpose of Local Maps\n\n- A **local area map** shows features in your immediate surroundings — your school, neighbourhood, or town\n- These maps help us understand the **layout** of places and navigate between them\n- They develop essential **spatial thinking** skills\n\n### Steps for Drawing a Local Area Map\n\n| Step | What to Do |\n|------|------------|\n| 1 | **Observe** your surroundings carefully — note major roads, buildings, and natural features |\n| 2 | **Orient** yourself — determine where north is (use a compass or the position of the sun) |\n| 3 | **Frame** your map — draw a neat border |\n| 4 | **Place major features** — start with the largest or most important features first |\n| 5 | **Add detail** — include smaller features, labels, and symbols |\n| 6 | **Create a key** — explain every symbol you have used |\n| 7 | **Add a title and north arrow** |\n\n### Common Map Symbols\n\n| Symbol | Meaning |\n|--------|----------|\n| Solid black line | Tarred road |\n| Dashed line | Untarred/gravel road |\n| Blue line | River or stream |\n| Green area | Park or vegetation |\n| Small square | Building |\n| Cross (+) | Church |\n| Flag symbol | School |'),
  q(2, 'What are the five essential features that every sketch map must include?',
    ['Title, north arrow, key (legend), labels, and a frame (border)', 'Only a title is needed', 'Just colour and drawings', 'Scale, temperature, weather, date, and time'], 0,
    'Every map — whether hand-drawn or printed — needs these five elements: a title (what the map shows), a north arrow (direction), a key/legend (explaining symbols), labels (naming features), and a frame (border). Without these, the map cannot be properly understood.'),
  t(3, '## Distance and Scale on Maps\n\nAccurate distance measurement is a key map skill.\n\n### Measuring Straight-Line Distance\n\n1. Place a ruler between two points on the map\n2. Read the distance in centimetres\n3. Use the scale to convert to real-world distance\n\n**Example:** If the distance between two towns on a 1:50 000 map is 8 cm:\n- 8 × 50 000 = 400 000 cm\n- 400 000 ÷ 100 000 = **4 km**\n\n### Measuring Curved (Road) Distance\n\n- Roads are rarely straight, so you cannot just use a ruler\n- **Method 1:** Use a piece of string, lay it along the curved road, then measure the string against a ruler\n- **Method 2:** Use the edge of a piece of paper, marking short sections along the curve, then total the distances\n\n### Word Scale, Number Scale, and Line Scale\n\n| If You Are Given | How to Use It |\n|-----------------|---------------|\n| **Word scale** ("1 cm represents 2 km") | Measure map distance in cm, then multiply by 2 km |\n| **Number scale** (1:200 000) | Map distance (cm) × 200 000, then convert cm to km |\n| **Line scale** | Place string/paper edge against the bar scale to read directly |\n\n### Converting Between Scale Types\n\n- Word scale → Number scale: "1 cm = 5 km" means 1:500 000 (because 5 km = 500 000 cm)\n- Number scale → Word scale: 1:50 000 means "1 cm represents 500 m"'),
  fb(4, 'To measure a curved road distance on a map, you can lay a piece of ___ along the road and then measure it with a ruler. The word scale "1 cm represents 5 km" is the same as the number scale 1:___.',
    ['string', '500 000'],
    'String follows curves easily, making it perfect for measuring winding roads on maps. To convert the word scale to a number scale: 5 km = 5 000 m = 500 000 cm, so the ratio is 1:500 000.'),
  t(5, '## Recording Land Use and Vegetation on a Map\n\nMaps can show what the land is used for and what type of vegetation grows in an area.\n\n### Land Use Categories\n\n| Category | Description | Map Colour/Symbol |\n|----------|-------------|--------------------|\n| **Residential** | Areas where people live (houses, flats) | Orange or pink |\n| **Commercial** | Shops, offices, banks | Red or dark pink |\n| **Industrial** | Factories, workshops, warehouses | Purple or grey |\n| **Agricultural** | Farms, crop fields, orchards | Yellow or light green |\n| **Recreational** | Parks, sports fields, playgrounds | Green |\n| **Transport** | Roads, railways, airports | Black or grey lines |\n| **Natural vegetation** | Forests, grasslands, fynbos | Dark green |\n\n### Types of Vegetation on Maps\n\n| Vegetation | Symbol |\n|------------|--------|\n| **Indigenous forest** | Closely spaced tree symbols |\n| **Plantation (forestry)** | Neat rows of tree symbols |\n| **Grassland** | Small tufts of grass |\n| **Cultivated land** | Regular field patterns |\n| **Scrub/fynbos** | Small bush symbols |\n\n### Observations From a Map\n\nFrom land use on a map, you can deduce:\n- Is the area mostly **rural** (farms, open land) or **urban** (buildings, roads)?\n- What is the **main economic activity** (farming, industry, mining)?\n- Is there **natural vegetation** or has it been cleared for farming?'),
  q(6, 'How can you tell from a map whether an area is rural or urban?',
    ['Rural areas show mostly farms and open land with few buildings, while urban areas show many buildings, roads, and little open land', 'All maps look the same', 'Rural areas are always coloured blue', 'Urban areas always have rivers'], 0,
    'On a map, rural areas typically show large open spaces, farm fields, scattered buildings, and natural vegetation. Urban areas show dense clusters of buildings, a network of roads, commercial and industrial zones, and very little open or natural land.'),
  t(7, '## Explaining Routes Using a Map\n\nBeing able to describe a route from one place to another using a map is an important practical skill.\n\n### How to Describe a Route\n\n1. **Identify the start and end points** on the map\n2. **Plan the route** — choose the most logical path (usually following roads)\n3. **Use compass directions**: "Travel north along Main Road"\n4. **Mention landmarks**: "Pass the school on your left"\n5. **Give distances** where possible: "Continue for approximately 2 km"\n6. **Note turns**: "Turn east (right) onto Church Street"\n\n### Example Route Description\n\n> "From the library, travel **north** along **King Street** for about **500 m**. At the intersection with **Church Street**, turn **east** (right). Continue for **300 m** past the park on your left. The hospital is on the **right-hand side** of Church Street."\n\n### Key Vocabulary for Route Descriptions\n\n| Word | Meaning |\n|------|----------|\n| **Intersection** | Where two roads cross |\n| **T-junction** | Where a road meets another and you can only turn left or right |\n| **Adjacent** | Next to |\n| **Opposite** | Directly across from |\n| **Parallel** | Running in the same direction alongside |'),
  fb(8, 'When describing a route on a map, you should use ___ directions such as north, south, east, and west. The point where two roads cross is called an ___.',
    ['compass', 'intersection'],
    'Using compass directions makes route descriptions clear and unambiguous. An intersection (or crossroads) is where two or more roads cross each other, and it is a key reference point when giving directions.'),
  q(9, 'Why is it important to mention landmarks when describing a route?',
    ['Landmarks help the person confirm they are on the right route and make directions easier to follow', 'Landmarks are only important on treasure maps', 'Mentioning landmarks makes directions too complicated', 'Maps do not show any landmarks'], 0,
    'Landmarks — like schools, churches, parks, and shops — serve as confirmation points. When you pass the landmark mentioned in the directions, you know you are on the right path. Without landmarks, it is easy to take a wrong turn.'),
  t(10, '## Putting It All Together: Map Skills Review\n\n### Essential Map Skills Checklist\n\nBy the end of this topic, you should be able to:\n\n| Skill | Description |\n|-------|-------------|\n| **Read a map** | Understand symbols, colours, and labels |\n| **Use the key** | Interpret symbols using the map\'s legend |\n| **Determine direction** | Use a compass or north arrow to find direction |\n| **Calculate distance** | Use scale to convert map distance to real distance |\n| **Give coordinates** | Use latitude and longitude to locate places |\n| **Draw a sketch map** | Create a simple map with all five essential features |\n| **Describe a route** | Give clear directions using compass directions and landmarks |\n| **Identify land use** | Recognise residential, commercial, industrial, and natural areas |\n\n### Why Map Skills Matter\n\n- Maps are used in **everyday life**: GPS, Google Maps, weather maps, news maps\n- Map skills help you understand **where things are** and **why they are there**\n- In Geography, map skills are assessed in **every term** and in the final examination\n- **Careers** that use map skills: town planners, surveyors, pilots, soldiers, delivery drivers, environmental scientists, geologists\n\n### Connection to Other Topics\n\nThe map skills you learn here will be used throughout Grade 7:\n- Locating volcanoes and earthquake zones on a world map\n- Mapping population distribution\n- Identifying natural resources on maps of South Africa\n- Understanding water availability across the country'),
];

// =============================================================================
// CHAPTER 3 (History – Term 2): The Transatlantic Slave Trade
// Focus: The nature and impact of the slave trade between West Africa
// and the American South
// =============================================================================

// --- Lesson 1: West Africa, the Slave Trade, and Slavery in America ---
blockNum = 0;
const ch3_lesson1 = [
  t(1, '## West Africa Before the European Slave Trade\n\nBefore the transatlantic slave trade began, West Africa was home to thriving kingdoms and societies with complex economies, cultures, and political systems.\n\n### Life in West Africa\n\n- West African societies were **diverse** — hundreds of different ethnic groups with their own languages, customs, and systems of government\n- Many people were **farmers**, growing crops like yams, millet, sorghum, and rice\n- **Trade** was well established — gold, salt, cloth, kola nuts, and iron were traded across the region\n- **Skilled crafts** flourished — metalworking (especially iron and gold), weaving, pottery, and woodcarving\n- Cities like Timbuktu, Kano, and Benin were centres of **learning and culture**\n\n### Slavery in Africa Before the Europeans\n\n- Slavery existed in Africa **before** the Europeans arrived, but it was very different:\n  - Enslaved people were usually **war captives** or **criminals**\n  - They often had **rights** — could marry, own property, and sometimes earn their freedom\n  - Their **children were usually born free**\n  - Slavery was not based on **race**\n- The European slave trade transformed slavery into something far more brutal and large-scale\n\n### The Nature of Slavery Before Europeans\n\n| African Slavery | European/Atlantic Slavery |\n|----------------|---------------------------|\n| Small scale | Massive scale (millions) |\n| Not based on race | Based on race (Africans = enslaved) |\n| Enslaved people had some rights | Enslaved people treated as property |\n| Children often born free | Children born into slavery |\n| Part of existing social systems | Part of a global economic system |'),
  q(2, 'How was slavery in Africa before the Europeans different from the transatlantic slave trade?',
    ['African slavery was smaller in scale, not race-based, and enslaved people had some rights — unlike the massive, race-based transatlantic system', 'There was no slavery in Africa before Europeans arrived', 'African slavery was more brutal than the transatlantic trade', 'There was no difference between the two systems'], 0,
    'Slavery existed in many societies throughout history, but the transatlantic slave trade was unique in its massive scale (millions of people), its racial basis (only Africans were enslaved), and its brutality (enslaved people were treated as property with no rights). This distinction is important for understanding the unique horror of the Atlantic system.'),
  t(3, '## The European Slave Trade Begins\n\nFrom the late 1400s, European powers began enslaving Africans and transporting them across the Atlantic Ocean to work in the Americas.\n\n### Why Did the Slave Trade Develop?\n\n| Factor | Explanation |\n|--------|-------------|\n| **European colonisation of the Americas** | Europeans established colonies and plantations (sugar, tobacco, cotton) in the Caribbean, Brazil, and North America |\n| **Labour demand** | Plantations needed huge numbers of workers — indigenous peoples were dying from European diseases |\n| **Profit** | Enslaved Africans were cheap labour that generated enormous wealth |\n| **Racism** | Europeans developed racist ideas to justify enslaving Africans |\n| **Guns and power** | Europeans had guns, ships, and military power to capture and transport people |\n\n### The Triangular Trade\n\nThe slave trade followed a **triangular pattern** across the Atlantic:\n\n| Leg | Route | Cargo |\n|-----|-------|-------|\n| **Leg 1** | Europe → West Africa | Guns, cloth, rum, metal goods |\n| **Leg 2** (Middle Passage) | West Africa → Americas | Enslaved Africans |\n| **Leg 3** | Americas → Europe | Sugar, tobacco, cotton, rum |\n\n### How Enslaved People Were Captured\n\n- Some were captured in **raids** by European slave traders\n- Many were captured in **wars between African kingdoms** and sold to European traders\n- Some African rulers participated in the slave trade, exchanging captives for European goods (especially guns)\n- Coastal African middlemen controlled much of the trade\n- An estimated **12-15 million Africans** were shipped across the Atlantic between the 1500s and the 1800s'),
  fb(4, 'The slave trade followed a triangular pattern across the ___. The second leg of this triangle, from West Africa to the Americas, was known as the ___ Passage.',
    ['Atlantic', 'Middle'],
    'The triangular trade connected Europe, Africa, and the Americas in a cycle of exploitation. The Middle Passage — the voyage from Africa to the Americas — was the most horrifying part, with enslaved people packed into ships under appalling conditions.'),
  t(5, '## The Middle Passage\n\nThe **Middle Passage** was the voyage across the Atlantic Ocean from West Africa to the Americas. It was one of the most horrific experiences in human history.\n\n### Conditions on Slave Ships\n\n- Enslaved people were packed **below deck** in spaces less than one metre high\n- They were **chained together** and could barely move\n- The voyage lasted **6 to 8 weeks** (sometimes longer)\n- There was almost no fresh air, light, or sanitation\n- Disease spread rapidly in the cramped, filthy conditions — **dysentery**, **smallpox**, and **scurvy** were common\n\n### The Human Cost\n\n| Aspect | Detail |\n|--------|--------|\n| **Mortality rate** | About **15-20%** of enslaved people died during the voyage |\n| **Disease** | Dysentery, smallpox, dehydration, and scurvy killed many |\n| **Suicide** | Some captives threw themselves overboard rather than endure slavery |\n| **Violence** | Captains and crew used whipping, branding, and other forms of torture |\n| **Starvation** | Food and water were inadequate; captives were often malnourished |\n| **Psychological trauma** | Terror, separation from family, loss of identity and freedom |\n\n### Slave Markets\n\nUpon arrival in the Americas:\n- Enslaved people were **cleaned up** and **oiled** to look healthy\n- They were sold at **slave markets** or **auctions**\n- Families were deliberately **separated** — husbands from wives, parents from children\n- Enslaved people were given **new names** by their owners, erasing their African identity'),
  q(6, 'What were conditions like during the Middle Passage?',
    ['Enslaved people were chained in cramped spaces below deck with little air, food, or sanitation, and about 15-20% died during the voyage', 'Enslaved people travelled in comfortable cabins', 'The voyage was short and safe', 'Enslaved people chose to make the journey voluntarily'], 0,
    'The Middle Passage was deliberately cruel. Ship captains maximised profits by packing as many people as possible into the hold. The conditions — no space to move, chains, disease, inadequate food — caused immense suffering and death. This was one of the greatest crimes in human history.'),
  t(7, '## Slavery in the American South\n\nEnslaved Africans who survived the Middle Passage were forced to work on **plantations** in the Americas — large farms that grew crops for export to Europe.\n\n### Plantation Crops\n\n| Crop | Location | Labour Required |\n|------|----------|------------------|\n| **Tobacco** | Virginia, Carolinas | Planting, tending, harvesting, curing |\n| **Sugar cane** | Caribbean, Brazil | Extremely hard labour; cutting, crushing, boiling |\n| **Cotton** | Southern USA (after 1790s) | Planting, weeding, picking by hand |\n| **Rice** | South Carolina, Georgia | Planting in flooded fields; very unhealthy |\n\n### Life on a Plantation\n\n- Enslaved people worked from **sunrise to sunset** — often **16 hours a day**\n- They were the **property** of their owners and had **no legal rights**\n- Owners could **beat**, **sell**, or **kill** enslaved people without punishment\n- Families were **split up** and sold separately\n- Enslaved people were forbidden to **read or write** — literacy was seen as dangerous\n- They received minimal food, clothing, and shelter\n\n### Slave Culture in Songs and Stories\n\n- Despite extreme oppression, enslaved people created a rich **culture**\n- **Songs** (spirituals) expressed pain, hope, and coded messages about escape\n- **Stories** passed down African traditions and values\n- **Religion** — enslaved people blended Christianity with African beliefs\n- This cultural resilience was a form of **resistance** against dehumanisation'),
  fb(8, 'The main plantation crops were tobacco, sugar cane, ___, and rice. Enslaved people were forbidden to read or ___ because slave owners feared that literacy would lead to rebellion.',
    ['cotton', 'write'],
    'Cotton became the most important plantation crop in the southern United States after the invention of the cotton gin in 1793. Slave owners deliberately kept enslaved people illiterate because they knew that education could lead to resistance and demands for freedom.'),
  q(9, 'Why did enslaved people create songs (spirituals) on the plantations?',
    ['To express their pain and hope, preserve African traditions, and sometimes send coded messages about escape', 'Because their owners wanted entertainment', 'They had no other way to pass the time', 'Songs were required by plantation rules'], 0,
    'Spirituals served multiple purposes: they expressed deep emotions, maintained African cultural traditions, strengthened community bonds, and sometimes contained coded messages. For example, "Follow the Drinking Gourd" gave directions for escaping north by following the Big Dipper constellation.'),
  t(10, '## The Raw Materials Enslaved People Produced\n\nThe wealth of the transatlantic slave trade went far beyond the sale of human beings. The products made by enslaved labour fuelled the global economy.\n\n### The Economics of Slavery\n\n- Enslaved labour was **unpaid** — plantation owners kept all the profits\n- The products (sugar, cotton, tobacco) were shipped to Europe and sold at high prices\n- Profits from slave-produced goods funded the **Industrial Revolution** in Britain and Europe\n- Banks, insurance companies, and shipping firms all grew wealthy from the slave trade\n\n### Cotton and the Industrial Revolution\n\n- **Raw cotton** from American slave plantations was shipped to factories in **Manchester** and other British cities\n- British factories turned raw cotton into **cloth** (textiles)\n- The finished cloth was then exported around the world — including back to Africa to trade for more enslaved people\n- Without slave-produced cotton, the British textile industry could not have grown as fast\n\n### Sugar and Wealth\n\n- **Sugar** was the most profitable slave-produced crop\n- Caribbean sugar plantations made their owners enormously wealthy\n- Sugar production was so brutal that enslaved people on sugar plantations had the **shortest life expectancy**\n- The profits from sugar helped fund British banks, universities, and grand houses\n\n### The Numbers\n\n- The slave trade lasted over **300 years** (roughly 1500s-1800s)\n- An estimated **12-15 million** Africans were transported across the Atlantic\n- Millions more died during capture, forced marches to the coast, and the Middle Passage\n- The slave trade\'s economic legacy shaped the modern world'),
];

// --- Lesson 2: Resistance to Slavery and the Abolition Movement ---
blockNum = 0;
const ch3_lesson2 = [
  t(1, '## Resistance to Slavery\n\nEnslaved people **never accepted** their enslavement passively. From the moment of capture, they resisted in many ways.\n\n### Forms of Resistance\n\n| Type | Examples |\n|------|----------|\n| **Everyday resistance** | Working slowly, pretending to be sick, breaking tools, "accidentally" burning crops |\n| **Maintaining culture** | Keeping African languages, music, dance, stories, and religious practices alive |\n| **Running away** | Escaping to freedom — some formed independent communities (called "maroon" communities) |\n| **Rebellion** | Organised uprisings against slave owners |\n| **Suicide** | Some chose death over enslavement — during the Middle Passage and on plantations |\n\n### Rebellion Against Slavery\n\nEnslaved people staged many rebellions:\n- **Nat Turner\'s Revolt (1831)** — in Virginia, USA; Turner and about 75 followers killed slave owners before being captured and executed\n- **Joseph Cinque and the Amistad Mutiny (1839)** — captives on the slave ship Amistad took control of the ship; they were eventually freed by a US court\n- **Haitian Revolution (1791-1804)** — the most successful slave revolt in history; enslaved people in Haiti overthrew French rule and established the first black republic\n\n### The Haitian Revolution\n\n- Led by **Toussaint L\'Ouverture** and later **Jean-Jacques Dessalines**\n- Enslaved people defeated the French, Spanish, and British armies\n- Haiti became independent on **1 January 1804**\n- It was the first successful large-scale slave revolt and inspired enslaved people everywhere'),
  q(2, 'What was the most successful slave revolt in history?',
    ['The Haitian Revolution (1791-1804), where enslaved people overthrew French rule and established an independent republic', 'Nat Turner\'s Revolt in Virginia', 'The Amistad Mutiny', 'No slave revolts ever succeeded'], 0,
    'The Haitian Revolution was extraordinary — enslaved people defeated the armies of three European powers (France, Spain, and Britain) and created the first black republic. It terrified slave owners throughout the Americas and inspired the global fight against slavery.'),
  t(3, '## The Underground Railroad\n\nThe **Underground Railroad** was a secret network of routes and safe houses used by enslaved people to escape to freedom in the northern United States and Canada.\n\n### How It Worked\n\n- It was not a real railroad — the name used railway terms as **code words**:\n  - **Stations** or **depots**: Safe houses where escapees could hide\n  - **Conductors**: People who guided escapees along the route\n  - **Passengers** or **cargo**: Enslaved people escaping to freedom\n  - **The Promised Land**: Canada (where slavery was illegal)\n\n### Harriet Tubman (c. 1822-1913)\n\n- **Harriet Tubman** was the most famous "conductor" on the Underground Railroad\n- She was born into slavery in Maryland\n- She escaped to freedom in **1849**\n- She then made approximately **13 trips** back to the South to rescue about **70 enslaved people**, including family members\n- She never lost a single "passenger"\n- She became known as the **"Moses of her people"**\n- Slave owners offered a reward of **$40 000** for her capture\n\n### Risks Involved\n\n- Escaping was extremely dangerous — if caught, enslaved people faced **severe beatings**, **torture**, or **death**\n- Those who helped them also faced legal punishment\n- Escapees travelled at **night** and used the **North Star** (Polaris) to navigate north\n- The journey could take **weeks or months**'),
  fb(4, 'Harriet ___ was the most famous conductor on the Underground Railroad and made about 13 trips to rescue enslaved people. Escapees used the ___ Star (Polaris) to navigate north to freedom.',
    ['Tubman', 'North'],
    'Harriet Tubman risked her life repeatedly to free others, showing extraordinary courage and determination. The North Star (Polaris) was crucial because it always appears in the northern sky, giving escapees a reliable guide when travelling at night.'),
  t(5, '## The Story of John Brown\n\n**John Brown** (1800-1859) was a white American abolitionist who believed that slavery could only be ended through **armed force**.\n\n### Brown\'s Mission\n\n- Brown was deeply religious and believed God had called him to **destroy slavery**\n- In **1859**, he led a raid on the **federal arsenal at Harpers Ferry**, Virginia (now West Virginia)\n- His plan was to seize weapons and arm enslaved people for a massive uprising\n- The raid **failed** — Brown was captured by soldiers led by Colonel Robert E. Lee\n\n### Trial and Execution\n\n- Brown was tried for treason, conspiracy, and murder\n- He was found guilty and **hanged** on **2 December 1859**\n- At his execution, he handed a note to a guard: *"I, John Brown, am now quite certain that the crimes of this guilty land will never be purged away but with blood"*\n\n### Impact\n\n- In the North, many saw Brown as a **hero and martyr**\n- In the South, he was seen as a **dangerous criminal**\n- His raid deepened the division between North and South\n- The **American Civil War** began less than two years later (1861-1865)\n- The Civil War ended slavery in the United States in **1865**'),
  q(6, 'Why is John Brown considered an important figure in the fight against slavery?',
    ['He was willing to use armed force to end slavery and his raid on Harpers Ferry deepened the division that led to the Civil War', 'He peacefully negotiated the end of slavery', 'He was a slave owner who freed his slaves', 'He invented the Underground Railroad'], 0,
    'John Brown believed that moral arguments alone would never end slavery and that armed resistance was necessary. Although his raid failed militarily, it galvanised both abolitionists and slave owners, making the conflict over slavery even more intense and helping to push the country toward the Civil War.'),
  t(7, '## The Abolition of Slavery\n\n**Abolition** means the ending or prohibition of something — in this case, slavery. The movement to end slavery gained strength through the 18th and 19th centuries.\n\n### The Abolition Movement\n\n| Key Figure | Contribution |\n|------------|-------------|\n| **William Wilberforce** | British MP who campaigned in Parliament for decades to end the slave trade |\n| **Olaudah Equiano** | Formerly enslaved African whose autobiography shocked British readers |\n| **Thomas Clarkson** | Gathered evidence of the horrors of the slave trade |\n| **Harriet Beecher Stowe** | Author of *Uncle Tom\'s Cabin* (1852), which turned public opinion against slavery |\n| **Frederick Douglass** | Escaped slave who became a powerful speaker and writer against slavery |\n\n### Key Dates\n\n| Date | Event |\n|------|-------|\n| **1807** | Britain abolished the **slave trade** (buying and selling slaves, not slavery itself) |\n| **1833** | Britain abolished **slavery** throughout the British Empire |\n| **1863** | US President Lincoln issued the **Emancipation Proclamation** |\n| **1865** | The 13th Amendment to the US Constitution abolished slavery in America |\n| **1888** | Brazil became the **last country** in the Americas to abolish slavery |\n\n### Why Was Slavery Abolished?\n\n- **Moral arguments**: Abolitionists argued that slavery was a sin and a violation of human rights\n- **Economic changes**: The Industrial Revolution made wage labour more profitable than slave labour in some industries\n- **Resistance**: Constant resistance by enslaved people (especially the Haitian Revolution) showed that slavery was unsustainable\n- **Political pressure**: Campaigners like Wilberforce worked for decades to change laws'),
  fb(8, 'Britain abolished the slave trade in 1807 and abolished slavery throughout the British Empire in ___. The last country in the Americas to abolish slavery was ___ in 1888.',
    ['1833', 'Brazil'],
    'The abolition of slavery was a long process. Even after Britain banned the slave trade in 1807, slavery itself continued in British colonies until 1833. In the Americas, Brazil was the last holdout, not abolishing slavery until 1888 — almost 400 years after the transatlantic slave trade began.'),
  q(9, 'What role did enslaved people\'s resistance play in ending slavery?',
    ['Constant resistance, especially the successful Haitian Revolution, proved that slavery was unsustainable and strengthened the abolition movement', 'Enslaved people did not resist and slavery ended on its own', 'Only white abolitionists fought to end slavery', 'Resistance actually made slavery last longer'], 0,
    'The resistance of enslaved people was crucial to ending slavery. The Haitian Revolution proved that enslaved people could overthrow their oppressors. Everyday resistance (sabotage, escape, rebellion) increased the costs of maintaining slavery and showed that it could never be secure.'),
  t(10, '## The Legacy of the Slave Trade\n\nThe transatlantic slave trade ended over 150 years ago, but its effects are still felt today.\n\n### Impact on Africa\n\n| Effect | Detail |\n|--------|--------|\n| **Population loss** | Millions of young, healthy people were taken — weakening economies and communities |\n| **Underdevelopment** | Africa was drained of human resources while Europe grew wealthy |\n| **Political instability** | Warfare caused by the slave trade destabilised regions for centuries |\n| **Cultural disruption** | Families and communities were torn apart |\n\n### Impact on the Americas\n\n- People of African descent now make up large populations in the USA, Brazil, the Caribbean, and throughout the Americas\n- **Racism** created to justify slavery persists today\n- African culture has profoundly influenced music (jazz, blues, hip-hop), food, language, and religion in the Americas\n- The economic **inequality** between black and white communities has roots in slavery\n\n### Impact on Europe\n\n- The slave trade made European countries — especially Britain, France, Spain, and Portugal — extremely wealthy\n- This wealth funded the **Industrial Revolution** and colonial expansion\n- European ports like **Liverpool**, **Bristol**, and **Nantes** grew rich from the slave trade\n- Many institutions (banks, universities) were built with slave trade profits\n\n### Remembering and Learning\n\n- Studying the slave trade helps us understand **how racism developed** and why it persists\n- It reminds us that **human rights** must be protected and defended\n- It shows the **courage** of those who resisted slavery and fought for abolition\n- The African Union and other organisations call for **recognition, education, and reparations**'),
];

// =============================================================================
// CHAPTER 4 (Geography – Term 2): Volcanoes, Earthquakes, and Floods
// =============================================================================

// --- Lesson 1: The Structure of the Earth, Volcanoes, and Earthquakes ---
blockNum = 0;
const ch4_lesson1 = [
  t(1, '## The Structure of the Earth\n\nTo understand volcanoes and earthquakes, we need to understand what the Earth looks like on the inside.\n\n### The Earth\'s Layers\n\n| Layer | Thickness | Composition | Temperature |\n|-------|-----------|-------------|-------------|\n| **Crust** | 5-70 km | Solid rock (thinner under oceans, thicker under continents) | Cool at surface |\n| **Mantle** | About 2 900 km | Semi-solid rock that flows very slowly (like thick honey) | Very hot (1 000-3 700°C) |\n| **Outer core** | About 2 200 km | Liquid iron and nickel | Extremely hot (4 000-5 000°C) |\n| **Inner core** | About 1 200 km radius | Solid iron and nickel (solid due to extreme pressure) | Hottest (5 000-6 000°C) |\n\n### The Crust and Tectonic Plates\n\n- The crust is **not one solid piece** — it is broken into large pieces called **tectonic plates**\n- There are about **15 major plates** and several smaller ones\n- These plates "float" on top of the semi-liquid mantle\n- The plates are constantly moving — very slowly, about **2-10 cm per year** (roughly as fast as your fingernails grow)\n- Where plates meet, we find **volcanoes**, **earthquakes**, and **mountain ranges**\n\n### Types of Crust\n\n| Type | Location | Thickness | Density |\n|------|----------|-----------|----------|\n| **Continental crust** | Under continents | 30-70 km | Less dense (lighter) |\n| **Oceanic crust** | Under oceans | 5-10 km | More dense (heavier) |'),
  q(2, 'Why do volcanoes and earthquakes occur at the boundaries of tectonic plates?',
    ['Because the movement and collision of plates creates pressure, friction, and openings that allow magma to reach the surface or cause the ground to shake', 'Because plates never move', 'Volcanoes and earthquakes happen randomly everywhere', 'Tectonic plates only exist in the ocean'], 0,
    'Tectonic plates are constantly moving. Where they push together, pull apart, or slide past each other, enormous forces build up. These forces cause earthquakes (sudden releases of energy) and create pathways for hot magma to rise to the surface (volcanoes).'),
  t(3, '## Plate Movements and Boundaries\n\nThere are three types of plate boundaries, and each produces different geological features.\n\n### Types of Plate Boundaries\n\n| Boundary Type | Movement | What Happens | Features Formed |\n|---------------|----------|-------------|------------------|\n| **Convergent** (destructive) | Plates move **towards** each other | One plate slides under the other (subduction) | Mountains, deep ocean trenches, volcanoes |\n| **Divergent** (constructive) | Plates move **apart** | Magma rises to fill the gap | Mid-ocean ridges, rift valleys, volcanoes |\n| **Transform** (conservative) | Plates slide **past** each other | Friction causes earthquakes | Fault lines (e.g., San Andreas Fault) |\n\n### The Ring of Fire\n\n- The **Ring of Fire** is a horseshoe-shaped zone around the **Pacific Ocean** where most of the world\'s volcanoes and earthquakes occur\n- About **75% of the world\'s active volcanoes** are in the Ring of Fire\n- About **90% of earthquakes** occur along it\n- Countries in the Ring of Fire include: Japan, Indonesia, Philippines, Chile, Peru, western USA, New Zealand\n\n### Why Is Africa Relatively Safe?\n\n- Most of Africa sits on the **African Plate**, far from plate boundaries\n- This is why Africa has **few active volcanoes** and fewer major earthquakes than countries on the Ring of Fire\n- However, the **East African Rift Valley** is a divergent boundary where the African Plate is slowly splitting apart'),
  fb(4, 'When two plates move towards each other, it is called a ___ (destructive) boundary. About 75% of the world\'s active volcanoes are found in the ___ of Fire around the Pacific Ocean.',
    ['convergent', 'Ring'],
    'At convergent boundaries, one plate is pushed under the other (subduction), creating enormous pressure that forms mountains and causes volcanic eruptions. The Ring of Fire encircles the Pacific Ocean and is the world\'s most geologically active zone.'),
  t(5, '## Volcanoes\n\nA **volcano** is an opening in the Earth\'s crust through which **magma** (molten rock), **ash**, and **gases** escape from deep underground.\n\n### How Volcanoes Form\n\n1. Deep underground, extreme heat melts rock into **magma**\n2. Magma is lighter than solid rock, so it rises towards the surface\n3. When magma reaches the surface through a crack or vent, it is called **lava**\n4. Lava and ash build up around the vent, forming a **cone-shaped mountain**\n5. The bowl-shaped opening at the top is called the **crater**\n\n### Types of Volcanoes\n\n| Type | Shape | Eruption | Example |\n|------|-------|----------|----------|\n| **Shield volcano** | Broad, gentle slopes | Quiet, flowing lava | Mauna Loa (Hawaii) |\n| **Composite (stratovolcano)** | Tall, steep cone | Explosive — ash, lava, gases | Mount Fuji (Japan), Vesuvius (Italy) |\n| **Cinder cone** | Small, steep | Short, explosive bursts | Parícutin (Mexico) |\n\n### Volcanic Activity Status\n\n| Status | Meaning |\n|--------|----------|\n| **Active** | Has erupted recently and is likely to erupt again |\n| **Dormant** | Has not erupted for a long time but could erupt again |\n| **Extinct** | Has not erupted for thousands of years and is unlikely to erupt again |\n\n### Why Do People Live Near Volcanoes?\n\n- **Fertile soil**: Volcanic ash creates very rich, productive farmland\n- **Geothermal energy**: Heat from volcanoes can generate electricity\n- **Tourism**: Volcanoes attract tourists\n- **Minerals**: Volcanic regions often have valuable mineral deposits'),
  q(6, 'What is the difference between magma and lava?',
    ['Magma is molten rock underground; when it reaches the surface through a volcano, it is called lava', 'They are the same thing', 'Lava is underground and magma is on the surface', 'Magma is a type of gas and lava is liquid'], 0,
    'The distinction is simple but important: magma is molten rock while it is still underground. The moment it reaches the Earth\'s surface — flowing out of a volcanic vent — it is called lava. Lava cools and hardens to form new rock.'),
  t(7, '## Earthquakes\n\nAn **earthquake** is a sudden shaking of the ground caused by the release of energy stored in rocks along a **fault** (crack in the Earth\'s crust).\n\n### How Earthquakes Happen\n\n1. Tectonic plates are constantly moving and pushing against each other\n2. **Friction** between plates prevents them from sliding smoothly\n3. **Pressure (stress)** builds up over time along the fault\n4. When the pressure becomes too great, the rocks suddenly **snap** and move — releasing energy\n5. This energy travels through the ground as **seismic waves**, causing the ground to shake\n\n### Earthquake Terminology\n\n| Term | Definition |\n|------|------------|\n| **Focus (hypocentre)** | The point underground where the earthquake starts |\n| **Epicentre** | The point on the surface directly above the focus |\n| **Fault** | A crack in the Earth\'s crust along which movement occurs |\n| **Seismic waves** | Waves of energy that travel through the ground |\n| **Aftershock** | Smaller earthquakes that follow the main earthquake |\n| **Richter scale** | A scale used to measure earthquake **magnitude** (strength) |\n\n### The Richter Scale\n\n| Magnitude | Effect |\n|-----------|--------|\n| **1-2** | Not felt by people; recorded by instruments |\n| **3-4** | Felt by some people; slight shaking |\n| **5-6** | Causes damage to buildings; felt widely |\n| **7-8** | Major earthquake — widespread destruction |\n| **9+** | Devastating — can destroy entire cities |'),
  fb(8, 'The point underground where an earthquake starts is called the ___. The point on the surface directly above it is called the ___.',
    ['focus', 'epicentre'],
    'The focus (also called the hypocentre) is where the actual rock movement occurs underground. The epicentre is the point on the surface directly above it and is usually where the shaking is strongest and damage is worst.'),
  q(9, 'How can people prepare for and reduce the impact of earthquakes?',
    ['By building earthquake-resistant structures, practising emergency drills, creating early warning systems, and having disaster plans', 'Earthquakes can be prevented entirely', 'There is nothing anyone can do', 'By moving away from all fault lines'], 0,
    'While earthquakes cannot be prevented, their impact can be reduced through preparation. Earthquake-resistant buildings use flexible materials and special foundations. Japan, for example, has strict building codes and regular earthquake drills that save many lives.'),
  t(10, '## Effects of Earthquakes\n\nEarthquakes can have devastating effects on people and the environment.\n\n### Effects on People and the Built Environment\n\n| Effect | Detail |\n|--------|--------|\n| **Building collapse** | Structures not built to withstand shaking can collapse, trapping and killing people |\n| **Fires** | Gas pipes break and electrical lines snap, causing fires |\n| **Infrastructure damage** | Roads, bridges, railways, and pipelines are damaged |\n| **Loss of services** | Water, electricity, and communication systems fail |\n| **Displacement** | People lose their homes and must live in temporary shelters |\n| **Economic losses** | Billions of rands in damage to buildings and infrastructure |\n| **Death and injury** | Major earthquakes can kill thousands of people |\n\n### Tsunamis\n\n- An undersea earthquake can cause a **tsunami** — a series of massive ocean waves\n- In the open ocean, tsunami waves are small, but they travel extremely fast (up to **800 km/h**)\n- As they approach the shore, they slow down and can reach heights of **30 metres or more**\n- The **2004 Indian Ocean tsunami** killed approximately **230 000 people** across 14 countries\n- Tsunami warning systems can save lives by giving coastal communities time to evacuate\n\n### Preparing for Earthquakes\n\n- **Building codes**: Earthquake-resistant designs use flexible materials and deep foundations\n- **Emergency drills**: Practising "Drop, Cover, Hold On"\n- **Early warning systems**: Seismographs detect earthquakes and can trigger warnings\n- **Disaster plans**: Families and communities should have emergency supplies and meeting points'),
];

// --- Lesson 2: Floods —  Causes, Effects, and Responses ---
blockNum = 0;
const ch4_lesson2 = [
  t(1, '## What Are Floods?\n\nA **flood** occurs when water covers land that is normally dry. Floods are the most common natural disaster worldwide and affect millions of people every year.\n\n### Causes of Floods\n\n| Cause | Explanation |\n|-------|-------------|\n| **Heavy rainfall** | Unusually heavy or prolonged rain causes rivers to overflow |\n| **Tropical cyclones** | Intense storms bring massive rainfall and storm surges |\n| **Deforestation** | Trees absorb rainfall; removing them means more water flows into rivers |\n| **Urbanisation** | Concrete and tar do not absorb water, so rainfall runs off into drains and rivers |\n| **Poor drainage** | Blocked or inadequate drainage systems cause flooding in urban areas |\n| **Dam failure** | A dam wall breaking releases a sudden surge of water |\n| **Coastal flooding** | Storm surges and high tides flood coastal areas |\n\n### Environmental Factors\n\n- **Steep slopes**: Water runs off quickly, causing flash floods\n- **Saturated soil**: Soil that is already wet cannot absorb more water\n- **Clay soils**: Clay does not absorb water well, leading to more runoff\n- **Impermeable surfaces**: Roads, parking lots, and buildings prevent water from soaking into the ground\n\n### Types of Floods\n\n| Type | Description |\n|------|-------------|\n| **River (fluvial) flood** | A river overflows its banks after heavy rain |\n| **Flash flood** | Sudden flooding caused by intense rainfall in a short time |\n| **Coastal flood** | Sea water floods coastal land due to storms or high tides |\n| **Urban flood** | Flooding in cities due to overloaded drainage systems |'),
  q(2, 'How does deforestation contribute to flooding?',
    ['Trees absorb rainfall and hold soil in place — removing them means more water flows directly into rivers, increasing flood risk', 'Deforestation has no effect on flooding', 'Trees cause flooding by blocking rivers', 'Deforestation only affects temperature'], 0,
    'Trees and their root systems act like natural sponges, absorbing rainfall and releasing it slowly. When forests are cleared, rainwater flows directly over the surface into rivers and streams, causing them to rise much faster. Deforestation also increases soil erosion, which can block river channels.'),
  t(3, '## Effects of Floods\n\nFloods cause widespread damage to people, property, and the environment.\n\n### Effects on People\n\n| Effect | Detail |\n|--------|--------|\n| **Death and injury** | Drowning, injuries from debris, disease from contaminated water |\n| **Displacement** | People lose their homes and must live in shelters or with relatives |\n| **Disease** | Waterborne diseases (cholera, typhoid) spread in floodwater |\n| **Loss of livelihoods** | Farmers lose crops and livestock; businesses are damaged |\n| **Emotional trauma** | Loss of loved ones and possessions causes lasting psychological harm |\n| **Food shortages** | Crops are destroyed, leading to hunger and higher food prices |\n\n### Effects on the Environment\n\n- **Soil erosion**: Floodwater strips away fertile topsoil\n- **Water pollution**: Sewage, chemicals, and waste are carried into rivers and water sources\n- **Habitat destruction**: Wetlands and river ecosystems are disrupted\n- **Sedimentation**: Mud and sand deposited by floods can block rivers and damage ecosystems\n\n### Effects on Infrastructure\n\n- Roads, bridges, and railways are washed away or damaged\n- Water treatment plants and sewage works may be flooded, contaminating drinking water\n- Power lines and electrical stations are damaged, causing blackouts\n- Schools and hospitals may be flooded and unable to function\n\n### South African Context\n\n- South Africa experiences frequent flooding, especially in **KwaZulu-Natal** and the **Eastern Cape**\n- In April 2022, devastating floods in **eThekwini** (Durban) killed over **400 people** and destroyed thousands of homes\n- Informal settlements on **floodplains** are particularly vulnerable'),
  fb(4, 'In April 2022, devastating floods in ___ (Durban) killed over 400 people. People living in informal settlements on ___ are particularly vulnerable to flooding.',
    ['eThekwini', 'floodplains'],
    'The 2022 KwaZulu-Natal floods were one of South Africa\'s worst natural disasters. Floodplains — flat areas next to rivers that naturally flood — are dangerous places to live, but many informal settlements are built there because other land is not available.'),
  t(5, '## Reducing the Impact of Floods\n\nWhile floods cannot be completely prevented, their impact can be reduced through preparation and good planning.\n\n### Before a Flood (Preparation)\n\n| Action | Purpose |\n|--------|----------|\n| **Early warning systems** | Give people time to evacuate before flooding occurs |\n| **Building restrictions** | Prevent building in flood-prone areas (floodplains) |\n| **Maintaining drainage** | Keep stormwater drains and channels clear of rubbish |\n| **Planting trees** | Trees absorb rainfall and hold soil in place |\n| **Building flood walls/levees** | Barriers to keep floodwater away from settlements |\n| **Disaster plans** | Communities and families prepare emergency plans |\n\n### During a Flood\n\n- **Evacuate** if told to do so by authorities\n- Move to **higher ground** immediately\n- Do **not** walk or drive through floodwater — it takes only 15 cm of fast-moving water to knock a person down\n- Avoid rivers and streams during heavy rain\n- Listen to emergency broadcasts on the radio\n\n### After a Flood\n\n- Do not drink water from taps until authorities confirm it is safe\n- Watch for damaged roads, bridges, and power lines\n- Help neighbours and community members who are affected\n- Report damage to local authorities\n- Beware of waterborne diseases — boil drinking water'),
  q(6, 'Why should people never walk or drive through floodwater?',
    ['Even shallow floodwater (15 cm) can knock people down, hide dangers like open drains, and vehicles can be swept away in deeper water', 'Floodwater is always clean and safe', 'Floodwater is only dangerous if it is very deep', 'Only children are at risk in floodwater'], 0,
    'Floodwater is extremely dangerous. Just 15 cm of fast-moving water can knock an adult off their feet. Water 60 cm deep can sweep away a car. Floodwater also hides dangers like open manholes, sharp debris, and live electrical wires.'),
  t(7, '## Case Study: A South African Flood\n\n### The KwaZulu-Natal Floods (April 2022)\n\nIn April 2022, catastrophic flooding struck the **eThekwini Metropolitan Municipality** (Durban) and surrounding areas in KwaZulu-Natal.\n\n### What Happened?\n\n| Aspect | Detail |\n|--------|--------|\n| **Cause** | A **cut-off low pressure system** brought extraordinarily heavy rainfall — over **300 mm in 24 hours** |\n| **Duration** | Heavy rain fell over several days (11-12 April 2022) |\n| **Deaths** | Over **400 people** lost their lives |\n| **Displacement** | Approximately **40 000 people** were displaced |\n| **Homes destroyed** | Over **12 000 homes** damaged or destroyed |\n| **Infrastructure** | Roads, bridges, water treatment plants, and the Port of Durban were severely damaged |\n\n### Why Was the Damage So Severe?\n\n1. **Informal settlements**: Many people lived in informal housing on steep slopes and floodplains that are highly vulnerable to flooding\n2. **Deforestation**: Loss of natural vegetation increased runoff\n3. **Poor drainage**: Stormwater systems could not cope with the volume of water\n4. **Climate change**: Scientists say climate change is making extreme rainfall events more frequent and intense\n5. **Inequality**: The poorest communities suffered the most because they lived in the most vulnerable locations\n\n### Response and Recovery\n\n- The South African National Defence Force (SANDF) assisted with rescue operations\n- Emergency shelters were set up for displaced families\n- The government pledged billions of rands for rebuilding\n- Calls were made for better urban planning and building regulations'),
  fb(8, 'The April 2022 KwaZulu-Natal floods were caused by a cut-off low pressure system that brought over ___ mm of rainfall in 24 hours. Over ___ people lost their lives.',
    ['300', '400'],
    'The intensity of the rainfall — over 300 mm in 24 hours — was extreme even for Durban\'s typically wet climate. The combination of intense rain, vulnerable settlements, and inadequate infrastructure turned a natural weather event into a major disaster.'),
  q(9, 'How does climate change affect the frequency and intensity of floods?',
    ['Climate change is causing more extreme rainfall events because warmer air holds more moisture, leading to heavier downpours and more frequent flooding', 'Climate change has no effect on floods', 'Climate change only affects temperatures, not rainfall', 'Floods are decreasing because of climate change'], 0,
    'Warmer temperatures cause more water to evaporate from oceans and land. Warmer air can hold more moisture (about 7% more for every 1°C increase). When this moisture-laden air releases its water, the rainfall is heavier and more intense, increasing the risk of devastating floods.'),
  t(10, '## Linking Volcanoes, Earthquakes, and Floods\n\nAlthough volcanoes, earthquakes, and floods are different natural hazards, they are connected in important ways.\n\n### Connections Between Hazards\n\n| Link | Explanation |\n|------|-------------|\n| **Earthquakes → Tsunamis** | Undersea earthquakes cause tsunamis (giant waves) that flood coastal areas |\n| **Volcanic eruptions → Floods** | Eruptions can melt glaciers or ice caps, causing devastating floods (lahars) |\n| **Earthquakes → Landslides** | Shaking can trigger landslides that block rivers, creating temporary dams that later burst |\n| **All three → Climate effects** | Large volcanic eruptions release particles that temporarily cool global temperatures |\n\n### Human Responses\n\nFor all three hazards, the key principles are the same:\n1. **Understand the risks**: Know where hazards are most likely\n2. **Prepare**: Have plans, supplies, and early warning systems\n3. **Build wisely**: Use appropriate building techniques and avoid dangerous locations\n4. **Respond quickly**: Effective emergency response saves lives\n5. **Recover and learn**: Rebuild better and learn from each disaster\n\n### Why Study Natural Hazards?\n\n- Understanding natural hazards helps us **protect lives** and **reduce damage**\n- South Africa is relatively safe from volcanoes and major earthquakes but is vulnerable to **floods**\n- **Climate change** is increasing the frequency and intensity of extreme weather events\n- Every community should have a **disaster management plan**'),
];

// =============================================================================
// CHAPTER 5 (History – Term 3): Colonisation of the Cape 17th–18th Centuries
// =============================================================================

// --- Lesson 1: The Dutch Settlement at the Cape ---
blockNum = 0;
const ch5_lesson1 = [
  t(1, '## The Dutch East India Company (VOC) at the Cape\n\nIn **1652**, the **Dutch East India Company (VOC)** established a refreshment station at the **Cape of Good Hope** under the command of **Jan van Riebeeck**.\n\n### Why Did the Dutch Come to the Cape?\n\n| Reason | Explanation |\n|--------|-------------|\n| **Trade route** | The Cape was halfway between the Netherlands and the Dutch East Indies (Indonesia) — a key stop for ships |\n| **Fresh supplies** | Ships needed fresh water, vegetables, and meat for the long voyage |\n| **Scurvy** | Sailors suffered from scurvy (caused by lack of vitamin C) — fresh fruit and vegetables were needed |\n| **Competition** | The Dutch wanted to prevent other European powers (especially Portugal and Britain) from controlling the route |\n\n### The VOC\n\n- The **Vereenigde Oost-Indische Compagnie** (VOC) was the Dutch East India Company\n- It was one of the most powerful trading companies in history\n- The VOC traded in spices, silk, and other goods from Asia\n- The Cape settlement was not meant to be a colony — just a **refreshment station** for passing ships\n\n### Jan van Riebeeck\n\n- **Jan van Riebeeck** arrived at the Cape on **6 April 1652** with about 90 men\n- He was ordered to build a fort, grow vegetables, and trade cattle with the local Khoikhoi people\n- He planted a **bitter almond hedge** to separate the Dutch settlement from the Khoikhoi — one of the first acts of territorial division at the Cape'),
  q(2, 'Why did the Dutch East India Company establish a settlement at the Cape in 1652?',
    ['To provide fresh water, food, and supplies for Dutch ships travelling between the Netherlands and the East Indies', 'To conquer the local population', 'To mine gold and diamonds', 'To establish a university'], 0,
    'The Cape was strategically located halfway along the long voyage from Europe to Asia. The VOC needed a place where ships could stop to take on fresh water, vegetables, meat, and other supplies to prevent scurvy and replenish crews.'),
  t(3, '## The Indigenous People of the Cape\n\nWhen the Dutch arrived, the Cape was home to two main groups of indigenous people: the **Khoikhoi** and the **San**.\n\n### The Khoikhoi\n\n| Feature | Detail |\n|---------|--------|\n| **Economy** | Pastoralists — they herded **cattle** and **sheep** |\n| **Society** | Organised into **clans** led by **chiefs** |\n| **Lifestyle** | Semi-nomadic — moved with their herds to find grazing |\n| **Wealth** | Measured in cattle |\n| **Trade** | Traded cattle and sheep with the Dutch for copper, iron, tobacco, and alcohol |\n\n### The San\n\n| Feature | Detail |\n|---------|--------|\n| **Economy** | Hunter-gatherers — hunted game and gathered wild plants |\n| **Society** | Small, mobile groups without formal chiefs |\n| **Lifestyle** | Nomadic — moved constantly in search of food |\n| **Art** | Famous for their **rock art** found throughout southern Africa |\n| **Knowledge** | Expert knowledge of plants, animals, and the environment |\n\n### Dutch-Khoikhoi Relations\n\n- At first, relations were **peaceful** — the Khoikhoi traded cattle for Dutch goods\n- But as the Dutch settlement expanded, they took more and more **Khoikhoi land**\n- The Khoikhoi were pushed off their grazing land, losing their ability to herd cattle\n- Two **Khoikhoi-Dutch wars** were fought (1659-1660 and 1673-1677) — the Khoikhoi lost both\n- By the early 1700s, the Khoikhoi had lost most of their land, cattle, and independence'),
  fb(4, 'The Khoikhoi were ___ who herded cattle and sheep. The San were ___-gatherers who hunted game and collected wild plants.',
    ['pastoralists', 'hunter'],
    'The Khoikhoi and San had lived at the Cape for thousands of years before the Dutch arrived. The Khoikhoi depended on their cattle, so losing their grazing land to the Dutch was devastating. The San, as hunter-gatherers, were even more vulnerable because their way of life required large areas of open land.'),
  t(5, '## Slavery at the Cape\n\nThe Dutch brought **enslaved people** to the Cape from 1658, just six years after the settlement was founded.\n\n### Why Slaves Were Brought to the Cape\n\n- The VOC needed labour to build the settlement, farm the land, and do domestic work\n- The Khoikhoi refused to work as labourers for the Dutch\n- Free Dutch settlers (burghers) were too few and considered manual labour beneath them\n- Enslaved people provided the **cheap, forced labour** the settlement needed\n\n### Where Did the Slaves Come From?\n\n| Region | Details |\n|--------|----------|\n| **East Africa** | Mozambique and Madagascar |\n| **India** | Bengal, the Malabar Coast, and other regions |\n| **Southeast Asia** | Indonesia (the Dutch East Indies), Malaysia |\n| **West Africa** | Smaller numbers from the West African coast |\n\n### Life as a Slave at the Cape\n\n- Enslaved people worked on **farms** (wine, wheat, and cattle), in **homes** as domestic servants, and on **construction projects**\n- They were the **property** of their owners and had very few rights\n- Physical **punishment** (whipping, branding) was common\n- Enslaved people could be **sold** at any time, separating families\n- Some enslaved people were skilled workers — carpenters, builders, cooks, tailors\n- Despite their oppression, enslaved people maintained their cultural practices and contributed to Cape culture\n\n### Cultural Contributions\n\n- Islam was brought to the Cape by enslaved people and political exiles from the East Indies\n- **Cape Malay cuisine** (bobotie, bredie, samoosas) has its roots in the food traditions of enslaved people\n- The **Afrikaans language** was significantly influenced by the languages of enslaved people'),
  q(6, 'Why were enslaved people brought to the Cape from 1658?',
    ['The Dutch needed labour but the Khoikhoi refused to work for them and there were too few Dutch settlers willing to do manual work', 'The enslaved people asked to come to the Cape', 'The VOC wanted to create a multicultural society', 'Enslaved people were brought only for domestic work'], 0,
    'The Dutch settlement needed workers for farming, building, and domestic service. The Khoikhoi people had their own cattle-herding economy and refused to become servants. With too few willing Dutch labourers, the VOC resorted to importing enslaved people from its trading networks in Africa, India, and Southeast Asia.'),
  t(7, '## The Slave Legacy at the Cape — Religion of Islam and the Afrikaans Language\n\n### The Spread of Islam at the Cape\n\n- Enslaved Muslims from Indonesia, India, and Malaysia brought **Islam** to the Cape\n- Political prisoners from the East Indies, like **Sheikh Yusuf** (arrived 1694), helped establish Islam at the Cape\n- The first mosque in South Africa, the **Auwal Mosque** in Bo-Kaap, Cape Town, was founded in **1798**\n- Today, the Bo-Kaap community and the Cape Malay community maintain strong Islamic traditions\n- Islam gave enslaved people a sense of **identity, community, and dignity** under oppression\n\n### The Development of Afrikaans\n\n- **Afrikaans** developed as a new language at the Cape, blending:\n  - **Dutch** (the language of the colonisers)\n  - **Malay and Indonesian** words (from enslaved people)\n  - **Portuguese** (a common trade language)\n  - **Khoikhoi** words and structures\n- It was originally spoken by **enslaved people, Khoikhoi servants, and lower-class Dutch settlers**\n- Afrikaans was originally called "kitchen Dutch" or "Cape Dutch"\n- It is a truly **South African language** — created at the Cape by all the people who lived there\n\n### The Coloured Community\n\n- Over time, relationships (often forced) between Dutch settlers, enslaved people, Khoikhoi, and San produced a mixed community\n- This community became known as the **Coloured** (or mixed-heritage) community\n- They developed a unique culture, combining elements from all their diverse origins\n- The Coloured community has been central to Cape Town\'s culture, cuisine, music, and language'),
  fb(8, 'Sheikh ___ was a political prisoner from the East Indies who helped establish Islam at the Cape. The Afrikaans language developed as a blend of Dutch, Malay, Portuguese, and ___ languages.',
    ['Yusuf', 'Khoikhoi'],
    'Sheikh Yusuf of Makassar (modern Indonesia) was exiled to the Cape by the Dutch in 1694. He is regarded as one of the founders of Islam in South Africa. Afrikaans is a uniquely South African language that reflects the diverse peoples who shaped Cape society.'),
  q(9, 'How did enslaved people contribute to the culture of the Cape?',
    ['They brought Islam, influenced the development of Afrikaans, contributed Cape Malay cuisine, and shaped music, building styles, and traditions', 'They had no cultural impact', 'They only contributed labour', 'Their culture was completely destroyed'], 0,
    'Despite being enslaved, people from East Africa, India, Indonesia, and Malaysia profoundly influenced Cape culture. Cape Malay food, Islamic traditions, Afrikaans vocabulary, building styles, and music all carry the cultural heritage of enslaved people. Their contributions are a vital part of South African identity.'),
  t(10, '## The Expansion of Dutch Settlement\n\nFrom the 1670s onwards, the Dutch settlement at the Cape began to expand beyond the original refreshment station.\n\n### Free Burghers\n\n- In **1657**, the VOC released some employees from their contracts and allowed them to become **free burghers** (citizens) — independent farmers\n- Free burghers farmed in the **Liesbeek River valley** and later in **Stellenbosch** (founded 1679) and **Franschhoek**\n- They grew wheat and grapes (for wine) and raised cattle\n\n### The French Huguenots\n\n- In **1688-1689**, about **200 French Huguenots** (Protestant refugees fleeing religious persecution in France) arrived at the Cape\n- They settled mainly in **Franschhoek** ("French corner") and the surrounding valleys\n- They brought expertise in **wine-making** that helped establish the Cape wine industry\n- Within a generation, they were absorbed into the Dutch-speaking community\n\n### The Trekboers\n\n- Some settlers moved away from Cape Town into the interior — these were called **trekboers** (travelling farmers)\n- They were pastoralists, herding cattle and sheep across vast areas\n- They came into increasing **conflict** with the Khoikhoi and San over land and cattle\n- The trekboers lived far from government control and became **independent and self-sufficient**\n- Their expansion pushed indigenous people off their ancestral lands\n\n### Consequences of Expansion\n\n- The Khoikhoi lost their land, cattle, and independence — many became servants on Dutch farms\n- The San were driven into marginal areas; those who resisted were hunted and killed\n- The Cape Colony grew from a small outpost into a significant settlement\n- The foundations were laid for the conflicts and inequalities that would shape South Africa\'s future'),
];

// --- Lesson 2: Causes and Effects of Slave Resistance in the Cape ---
blockNum = 0;
const ch5_lesson2 = [
  t(1, '## Resistance to Slavery at the Cape\n\nEnslaved people at the Cape resisted their bondage in many ways — from everyday acts of defiance to organised rebellion.\n\n### Everyday Resistance\n\n| Form | Description |\n|------|-------------|\n| **Working slowly** | Deliberately slowing down work to reduce output |\n| **Pretending to be sick** | Avoiding work by claiming illness |\n| **Breaking tools** | Damaging equipment to disrupt work |\n| **Arson** | Setting fire to crops or buildings |\n| **Theft** | Stealing food or goods from owners |\n| **Maintaining culture** | Practising Islam, speaking home languages, keeping traditions alive |\n\n### Running Away (Desertion)\n\n- Running away was the **most common form of serious resistance**\n- Enslaved people fled into the mountains, forests, or to Khoikhoi communities\n- Some escaped to other parts of the colony or tried to reach Mozambique\n- Recaptured runaways faced severe punishment — whipping, branding, or even execution\n- Despite the risks, many enslaved people chose to flee\n\n### Why Was Resistance Important?\n\n- Resistance showed that enslaved people **never accepted** their condition\n- It forced slave owners to spend money on security and punishment\n- It created a constant atmosphere of **tension and fear** among slave owners\n- It demonstrated the **courage and humanity** of people who were treated as property'),
  q(2, 'What was the most common form of serious resistance among enslaved people at the Cape?',
    ['Running away (desertion) — despite the severe punishments if caught', 'Writing letters of complaint', 'Voting against slavery', 'Asking politely to be freed'], 0,
    'Running away was an act of tremendous courage. Enslaved people who fled risked severe punishment — whipping, branding, or death — if recaptured. Despite these risks, many chose to flee, seeking freedom in the mountains, with Khoikhoi communities, or by trying to leave the colony entirely.'),
  t(3, '## Free Burghers and the Expanding Frontier\n\nAs the Dutch settlement grew, **free burghers** (independent farmers) expanded further into the interior, coming into increasing contact and conflict with indigenous peoples.\n\n### The Expanding European Frontiers\n\n| Period | Area of Expansion |\n|--------|--------------------|\n| **1657-1670s** | Liesbeek Valley, Table Bay area |\n| **1679-1700s** | Stellenbosch, Drakenstein, Paarl, Franschhoek |\n| **1700s** | Swartland (wheat farming), Overberg |\n| **Late 1700s** | Far into the interior — Karoo, eastern frontier |\n\n### Conflict with Indigenous Peoples\n\n- As the Dutch expanded, they took more and more land from the **Khoikhoi** and **San**\n- Khoikhoi lost their **grazing land** and many became servants on Dutch farms\n- The San fought back with **guerrilla tactics** — raiding Dutch farms and stealing livestock\n- The Dutch organised **commandos** (armed groups) to hunt and kill San people\n- These commandos killed thousands of San men, women, and children\n- By the late 1700s, the Khoikhoi and San societies at the Cape had been largely destroyed\n\n### The Khoikhoi Response\n\n- Some Khoikhoi tried to **resist** Dutch expansion through war (1659-1660, 1673-1677)\n- Others tried to **negotiate** or trade peacefully\n- Many were forced to become **labourers** on Dutch farms\n- Disease (especially **smallpox** — devastating epidemics in 1713 and 1755) killed large numbers of Khoikhoi, further weakening their resistance'),
  fb(4, 'The Dutch organised armed groups called ___ to hunt and kill San people who resisted colonial expansion. Devastating ___ epidemics in 1713 and 1755 killed large numbers of Khoikhoi.',
    ['commandos', 'smallpox'],
    'Commandos were groups of armed settlers (and sometimes Khoikhoi servants) who carried out military campaigns against San communities. Smallpox, brought to the Cape by European ships, devastated the Khoikhoi because they had no immunity to this disease.'),
  t(5, '## Dutch and French Huguenot Immigration\n\n### The French Huguenots at the Cape\n\nThe **Huguenots** were French Protestants who fled France after King Louis XIV revoked the **Edict of Nantes** in 1685, which had protected their right to worship.\n\n### Their Arrival and Settlement\n\n| Aspect | Detail |\n|--------|--------|\n| **When** | 1688-1689 |\n| **Number** | About 200 people (men, women, and children) |\n| **Where** | Franschhoek, Drakenstein, Paarl (Western Cape) |\n| **Why they left France** | Religious persecution — they were Protestants in a Catholic country |\n| **Skills** | Farming, especially **wine-making** and fruit growing |\n\n### Their Contribution\n\n- The Huguenots brought **vine cultivation skills** from France\n- They established the Cape\'s **wine industry**, which is still world-famous today\n- Many well-known South African families have French Huguenot surnames: **Du Plessis, De Villiers, Joubert, Malherbe, Le Roux**\n- Within a generation, the Huguenots were **absorbed** into the Dutch-speaking community\n- The VOC deliberately mixed French and Dutch settlers to prevent a separate French community\n\n### The Huguenot Memorial in Franschhoek\n\n- The **Huguenot Memorial** in Franschhoek was built in **1948** to commemorate the Huguenots\' arrival\n- It is a popular tourist attraction and a reminder of the diverse origins of the Cape settler community'),
  q(6, 'What was the main contribution of the French Huguenots to the Cape Colony?',
    ['They established the wine-making industry, bringing vine cultivation skills from France', 'They introduced mining techniques', 'They built the first university', 'They established trade routes to Asia'], 0,
    'The French Huguenots were skilled in growing grapes and making wine, traditions they brought from their homeland in France. Their expertise laid the foundation for the Cape wine industry, which remains one of South Africa\'s most important agricultural sectors today.'),
  t(7, '## Lifestyles and Stories of the Trekboers\n\n### Who Were the Trekboers?\n\n- **Trekboers** were Dutch-speaking frontier farmers who moved away from Cape Town into the interior\n- The word "trek" means to "pull" or "travel" in Dutch/Afrikaans\n- They were **pastoralists**, raising cattle and sheep on large areas of land\n- They lived far from government authority and were **self-sufficient** — making their own clothes, furniture, and tools\n\n### Trekboer Lifestyle\n\n| Aspect | Detail |\n|--------|--------|\n| **Homes** | Simple houses made of mud and thatch; moved frequently |\n| **Economy** | Cattle and sheep farming; traded hides and butter |\n| **Family** | Large families; children educated at home (if at all) |\n| **Religion** | Calvinist Christians; the Bible was often the only book in the home |\n| **Society** | Independent, isolated; suspicious of government authority |\n| **Defence** | Each farmer had a gun; organised into commandos for mutual defence |\n\n### Relations with Indigenous Peoples\n\n- Trekboers competed directly with the Khoikhoi and San for **land and water**\n- They took the best grazing land and water sources for themselves\n- Khoikhoi who lost their land often became **servants** on trekboer farms\n- San who resisted were hunted by commandos — this amounted to **genocide** in some areas\n- Some Khoikhoi women married trekboer men, contributing to the mixed-heritage (Coloured) community\n\n### The Eastern Frontier\n\n- By the late 1700s, trekboers reached the **Fish River** area in the eastern Cape\n- Here they encountered the **Xhosa** people — a large, well-organised farming and herding community\n- This meeting of two expanding peoples — the trekboers moving east and the Xhosa moving west — led to a series of **frontier wars** that would continue for nearly a century'),
  fb(8, 'Trekboers were Dutch-speaking ___ farmers who moved into the interior of the Cape Colony. By the late 1700s, they reached the eastern frontier where they encountered the ___ people.',
    ['frontier', 'Xhosa'],
    'The trekboers\' relentless expansion eastward eventually brought them into contact with Xhosa chiefdoms along the Fish River. This clash between European settlers and African farmers over land and cattle would dominate South African history for the next century.'),
  q(9, 'Why did conflict develop between the trekboers and the San people?',
    ['The trekboers took San hunting grounds for cattle farming, and when the San resisted by raiding livestock, the trekboers organised commandos to kill them', 'The San attacked first without reason', 'There was no conflict between them', 'The San willingly gave up their land'], 0,
    'The San were hunter-gatherers who needed vast areas of open land to survive. When trekboers moved into their territory with cattle and sheep, the San lost their hunting grounds. When desperate San people raided settler livestock, the settlers organised commandos that killed San men, women, and children.'),
  t(10, '## The Cape by the End of the 18th Century\n\nBy **1795**, when the British first took control of the Cape, the settlement had changed dramatically from the small refreshment station of 1652.\n\n### How the Cape Had Changed\n\n| Feature | 1652 | 1795 |\n|---------|------|------|\n| **Population** | ~90 Dutch men | ~20 000 settlers, plus thousands of enslaved people and Khoikhoi servants |\n| **Purpose** | Refreshment station | Full colony with farms, towns, and an expanding frontier |\n| **Economy** | Growing vegetables for ships | Wine, wheat, and cattle farming; trade |\n| **Territory** | Table Bay area only | From the Cape to the Fish River (over 800 km) |\n| **Indigenous peoples** | Independent Khoikhoi and San | Most Khoikhoi dispossessed; San hunted; Xhosa on the frontier |\n| **Labour** | Dutch company employees | Enslaved people and Khoikhoi servants |\n\n### Key Themes\n\n1. **Land dispossession**: The Khoikhoi and San lost their land, cattle, and independence\n2. **Slavery**: Enslaved people from Africa and Asia built the colony\'s economy\n3. **Cultural mixing**: A new, diverse Cape society emerged — Dutch, Khoikhoi, enslaved people, French Huguenots\n4. **Inequality**: The colony was built on racial hierarchy — white settlers at the top, enslaved people at the bottom\n5. **Resistance**: Both enslaved people and indigenous peoples resisted colonial domination\n\n### Looking Ahead\n\n- The British took control of the Cape in **1795** (temporarily) and permanently in **1806**\n- British rule would bring new changes — the abolition of slavery (1834), new settlers, and escalating frontier conflict\n- The patterns established at the Cape — land dispossession, racial inequality, forced labour — would shape South Africa\'s future'),
];

// =============================================================================
// CHAPTER 6 (Geography – Term 3): Population Growth and Change
// =============================================================================

// --- Lesson 1: Population Concepts and World Population Growth ---
blockNum = 0;
const ch6_lesson1 = [
  t(1, '## Population Concepts\n\nThe study of population is called **demography**. Understanding population helps us plan for the future — how many schools, hospitals, houses, and jobs will be needed.\n\n### Key Population Terms\n\n| Term | Definition |\n|------|------------|\n| **Population** | The total number of people living in an area |\n| **Birth rate** | The number of live births per 1 000 people per year |\n| **Death rate** | The number of deaths per 1 000 people per year |\n| **Natural increase** | Birth rate minus death rate (if births exceed deaths, the population grows) |\n| **Population growth rate** | The rate at which a population increases or decreases, including migration |\n| **Life expectancy** | The average number of years a person is expected to live |\n| **Infant mortality rate** | The number of babies (under 1 year old) who die per 1 000 live births |\n| **Fertility rate** | The average number of children born to a woman during her lifetime |\n\n### Calculating Natural Increase\n\n**Natural increase = Birth rate − Death rate**\n\nExample:\n- Birth rate = 25 per 1 000\n- Death rate = 10 per 1 000\n- Natural increase = 25 − 10 = **15 per 1 000** (or 1.5%)\n\nIf natural increase is **positive**, the population is growing.\nIf it is **negative**, the population is shrinking.'),
  q(2, 'What is the difference between birth rate and fertility rate?',
    ['Birth rate is the number of births per 1 000 people per year, while fertility rate is the average number of children born to each woman during her lifetime', 'They are the same thing', 'Fertility rate is always higher than birth rate', 'Birth rate only counts male babies'], 0,
    'Birth rate measures births relative to the total population (both men and women), while fertility rate focuses on the average number of children per woman. A country can have a high fertility rate but a low birth rate if most of the population is elderly.'),
  t(3, '## World Population Growth\n\nThe world\'s population has grown enormously over time, especially in the last 200 years.\n\n### Population Growth Through History\n\n| Year | Approximate World Population |\n|------|------------------------------|\n| 1 AD | 300 million |\n| 1000 AD | 310 million |\n| 1500 | 500 million |\n| 1800 | 1 billion |\n| 1900 | 1.6 billion |\n| 1950 | 2.5 billion |\n| 1999 | 6 billion |\n| 2023 | 8 billion |\n| 2050 (est.) | 9.7 billion |\n\n### Pattern of World Population Growth\n\n- For most of human history, population grew very **slowly**\n- From about **1800 onwards**, population growth **accelerated dramatically**\n- This is shown on a graph as a **J-shaped curve** — slow growth followed by rapid increase\n- The world population took thousands of years to reach 1 billion, but only 12 years to grow from 7 to 8 billion\n\n### Why Did Population Growth Accelerate After 1800?\n\n| Factor | How It Reduced Deaths |\n|--------|-----------------------|\n| **Better farming** | More food = less famine |\n| **Medical advances** | Vaccines, antibiotics, and better hygiene reduced disease |\n| **Cleaner water** | Piped water and sanitation reduced waterborne diseases |\n| **Improved sanitation** | Sewage systems prevented disease outbreaks |\n| **Industrial Revolution** | Higher living standards for some |\n\nDeath rates dropped, but birth rates stayed high → **population explosion**'),
  fb(4, 'The world\'s population reached 1 billion around 1800 and has grown to approximately ___ billion by 2023. World population growth since 1800 follows a ___-shaped curve.',
    ['8', 'J'],
    'The dramatic acceleration in population growth after 1800 is largely due to improvements in medicine, food production, and sanitation that caused death rates to fall while birth rates remained high. The J-shaped curve illustrates how slowly population grew for thousands of years compared to the explosive growth of the last two centuries.'),
  t(5, '## Infant Mortality and Life Expectancy\n\n### Infant Mortality Rate (IMR)\n\n- IMR is the number of babies (under 1 year) who die per **1 000 live births**\n- It is one of the most important indicators of a country\'s development\n- High IMR suggests poor healthcare, nutrition, and sanitation\n\n| Country | IMR (approximate) |\n|---------|--------------------|\n| **Japan** | 2 per 1 000 (very low — excellent healthcare) |\n| **South Africa** | 25 per 1 000 (moderate) |\n| **Nigeria** | 72 per 1 000 (high) |\n| **Sierra Leone** | 80 per 1 000 (very high) |\n\n### Life Expectancy\n\n- Life expectancy is the average age a person can expect to live\n- It varies greatly between countries and is affected by **healthcare, nutrition, disease, conflict, and poverty**\n\n| Country | Life Expectancy (approximate) |\n|---------|-------------------------------|\n| **Japan** | 84 years |\n| **South Africa** | 65 years |\n| **Nigeria** | 55 years |\n| **Sierra Leone** | 55 years |\n\n### South Africa\'s Situation\n\n- South Africa\'s life expectancy dropped dramatically in the **2000s** due to the **HIV/AIDS epidemic**\n- It reached a low of about **52 years** around 2005\n- With the rollout of **antiretroviral treatment (ARVs)**, life expectancy has recovered to about **65 years**\n- South Africa\'s infant mortality rate has also improved but remains higher than in developed countries'),
  q(6, 'Why is the infant mortality rate considered an important indicator of a country\'s development?',
    ['Because a high IMR suggests poor healthcare, nutrition, sanitation, and access to clean water — all signs of low development', 'IMR is not important', 'Only wealthy countries track IMR', 'IMR only measures adult health'], 0,
    'The infant mortality rate reflects the overall health of a society. Babies are especially vulnerable, so a high IMR indicates that the country lacks adequate healthcare, clean water, nutrition, and sanitation. Developed countries with good healthcare systems have very low IMRs.'),
  t(7, '## Factors That Have Affected Population Growth\n\nThroughout history, various developments have influenced population size — some increasing it, others decreasing it.\n\n### Developments That Increased Population\n\n| Development | How It Helped |\n|-------------|---------------|\n| **Agriculture** | Farming produced more food than hunting and gathering |\n| **Medical discoveries** | Vaccines (e.g., smallpox, polio) saved millions of lives |\n| **Antibiotics** | Penicillin and other antibiotics cured bacterial infections |\n| **Clean water and sanitation** | Prevented waterborne diseases like cholera and typhoid |\n| **Improved nutrition** | Better food production meant fewer people died of hunger |\n| **Public health programmes** | Immunisation campaigns, health education |\n\n### Developments That Decreased Population\n\n| Factor | Impact |\n|--------|--------|\n| **Pandemics** | The Black Death (1300s) killed 75-200 million people |\n| **The Spanish Flu (1918-1919)** | Killed an estimated 50 million people worldwide |\n| **HIV/AIDS** | Has killed approximately 40 million people since the 1980s |\n| **Wars and conflicts** | World Wars I and II killed tens of millions |\n| **Famines** | Drought and failed crops caused mass starvation |\n\n### The COVID-19 Pandemic\n\n- COVID-19 (from 2020) killed millions of people worldwide\n- It is **not examinable** (as noted in the CAPS ATP)\n- However, it demonstrated how pandemics can rapidly affect population and economies'),
  fb(8, 'The Black Death in the 1300s killed an estimated ___-200 million people. The ___ flu pandemic of 1918-1919 killed approximately 50 million people.',
    ['75', 'Spanish'],
    'Pandemics have been among the most devastating population-reducing events in history. The Black Death killed roughly one-third of Europe\'s population. The Spanish flu killed more people than World War I, which had just ended.'),
  q(9, 'How did the HIV/AIDS epidemic affect South Africa\'s population?',
    ['It caused life expectancy to drop to about 52 years by 2005 and killed millions of people before ARV treatment became widely available', 'It had no effect on South Africa', 'It only affected other countries', 'It increased the population'], 0,
    'South Africa was one of the countries hardest hit by HIV/AIDS. At the peak of the epidemic, life expectancy dropped from about 63 years to 52 years. The rollout of antiretroviral (ARV) treatment from the mid-2000s has allowed life expectancy to recover to about 65 years.'),
  t(10, '## Economic Status and Population\n\nThere is a strong link between a country\'s **economic development** and its population patterns.\n\n### Developed vs Developing Countries\n\n| Feature | Developed Countries | Developing Countries |\n|---------|--------------------|-----------------------|\n| **Birth rate** | Low | High |\n| **Death rate** | Low | Moderate to high |\n| **Natural increase** | Low (sometimes negative) | High |\n| **Life expectancy** | High (75-85 years) | Lower (50-70 years) |\n| **Infant mortality** | Very low (2-8 per 1 000) | Higher (30-80 per 1 000) |\n| **Population structure** | More elderly people | More young people |\n\n### Why Do Developing Countries Have Higher Birth Rates?\n\n1. **Children as workers**: Families need children to help with farming and earning income\n2. **No pension/social security**: Children support parents in old age\n3. **High infant mortality**: Families have more children because some may die\n4. **Limited access to family planning**: Fewer contraceptives and less education\n5. **Cultural and religious factors**: Large families may be valued\n\n### Conflict and Wars\n\nArmed conflict affects population through:\n- **Direct deaths** in fighting\n- **Displacement**: Refugees flee their homes\n- **Destruction of healthcare and food systems**: Leading to disease and famine\n- **Economic collapse**: Poverty increases death rates\n\nSouth Africa, as a **developing country**, has characteristics of both groups — moderate birth rates, moderate life expectancy, and a young population with high unemployment.'),
];

// --- Lesson 2: Developments That Affected Population and Improved Healthcare ---
blockNum = 0;
const ch6_lesson2 = [
  t(1, '## Scientific Developments and Population Growth\n\nScientific discoveries have been the single most important factor in increasing world population by reducing death rates.\n\n### Key Medical Discoveries\n\n| Discovery | Date | Impact |\n|-----------|------|--------|\n| **Smallpox vaccine** | 1796 (Edward Jenner) | First vaccine; smallpox eventually eradicated in 1980 |\n| **Germ theory** | 1860s (Louis Pasteur) | Understanding that germs cause disease led to hygiene and sterilisation |\n| **Antiseptics** | 1867 (Joseph Lister) | Reduced surgical infections; saved countless lives |\n| **Penicillin** | 1928 (Alexander Fleming) | First antibiotic; cured bacterial infections |\n| **Oral rehydration therapy** | 1960s | Simple, cheap treatment for diarrhoea — saved millions of children |\n| **HIV/AIDS treatment (ARVs)** | 1990s onwards | Antiretroviral drugs allow people with HIV to live longer |\n\n### Improved Sanitation\n\n- **Clean drinking water**: Piped water systems replaced contaminated rivers and wells\n- **Sewage systems**: Proper disposal of human waste prevented diseases like cholera and typhoid\n- **Rubbish removal**: Reduced disease-carrying pests (rats, flies)\n- These improvements were among the **most effective** ways of reducing death rates\n\n### Improved Food Production\n\n- The **Agricultural Revolution** (1700s) introduced crop rotation, selective breeding, and new tools\n- The **Green Revolution** (1960s-1970s) introduced high-yield crop varieties, fertilisers, and irrigation\n- Modern farming produces far more food per hectare than ever before\n- Despite this, hunger and malnutrition still affect millions — food distribution is unequal'),
  q(2, 'Why was the discovery of penicillin so important for population growth?',
    ['Penicillin was the first antibiotic, curing previously deadly bacterial infections like pneumonia, sepsis, and wound infections', 'Penicillin cured all diseases', 'Penicillin was only used in one country', 'Penicillin had no effect on population'], 0,
    'Before penicillin (discovered by Alexander Fleming in 1928), even minor wounds could lead to fatal infections. Penicillin and subsequent antibiotics saved millions of lives by curing diseases like pneumonia, tuberculosis, and infections from wounds or surgery.'),
  t(3, '## Improved Healthcare in South Africa\n\n### South Africa\'s Healthcare System\n\n| Sector | Description |\n|--------|-------------|\n| **Public healthcare** | Government hospitals and clinics; serves the majority of the population; often under-resourced |\n| **Private healthcare** | Private hospitals and doctors; excellent quality but expensive; used by those with medical aid |\n\n### Key Health Programmes\n\n- **Expanded Programme on Immunisation (EPI)**: Free vaccines for all children against measles, polio, tuberculosis, and other diseases\n- **ARV rollout**: South Africa has the world\'s largest antiretroviral treatment programme for HIV/AIDS\n- **Primary healthcare clinics**: Free basic healthcare for all at government clinics\n- **National Health Insurance (NHI)**: A planned system to provide universal healthcare for all South Africans\n\n### Challenges\n\n| Challenge | Detail |\n|-----------|--------|\n| **Inequality** | A "two-tier" system — excellent private care for the wealthy, overburdened public care for the poor |\n| **HIV/AIDS** | South Africa has one of the highest HIV rates in the world (approximately 8 million people) |\n| **Tuberculosis (TB)** | South Africa has high rates of TB, often linked to HIV |\n| **Staff shortages** | Many doctors and nurses emigrate for better pay overseas |\n| **Infrastructure** | Rural clinics often lack equipment and medicine |'),
  fb(4, 'South Africa has the world\'s largest ___ treatment programme for HIV/AIDS. The country\'s healthcare system is described as "two-tier" because of the gap between public and ___ healthcare.',
    ['antiretroviral', 'private'],
    'South Africa\'s massive ARV rollout has saved millions of lives and dramatically increased life expectancy. However, the gap between excellent private healthcare (for those who can afford it) and under-resourced public healthcare (for the majority) remains one of the country\'s biggest challenges.'),
  t(5, '## Population Pyramids\n\nA **population pyramid** (also called an age-sex pyramid) is a graph that shows the age and sex structure of a population.\n\n### How to Read a Population Pyramid\n\n- The **horizontal axis** shows the number or percentage of people\n- The **vertical axis** shows age groups (usually in 5-year intervals)\n- **Males** are shown on the left; **females** on the right\n- The youngest age groups are at the **bottom**; the oldest at the **top**\n\n### Types of Population Pyramids\n\n| Shape | What It Shows | Example Countries |\n|-------|--------------|--------------------|\n| **Wide base, narrow top** (triangular) | High birth rate, high death rate, short life expectancy; many young people | Nigeria, Mozambique |\n| **Narrowing base, wider middle** (barrel-shaped) | Declining birth rate; moderate death rate; population growth slowing | South Africa, Brazil |\n| **Narrow base, wide middle and top** (urn-shaped) | Low birth rate, low death rate, long life expectancy; ageing population | Japan, Germany |\n\n### What Population Pyramids Tell Us\n\n- A wide base means many children → need for schools and child healthcare\n- A bulge in the middle means many working-age adults → need for jobs\n- A wide top means many elderly people → need for pensions and elderly care\n- South Africa has a **relatively young population** — about 30% are under 15 years old'),
  q(6, 'What does a population pyramid with a very wide base and narrow top indicate?',
    ['A high birth rate, high death rate, short life expectancy, and many young people — typical of developing countries', 'A wealthy, ageing population', 'A declining population', 'Equal numbers at all ages'], 0,
    'A triangular population pyramid with a very wide base shows that many children are being born (high birth rate) but many people are dying young (high death rate). This shape is typical of less developed countries where healthcare, nutrition, and sanitation may be limited.'),
  t(7, '## Pandemics of the Past\n\nThroughout history, pandemics (disease outbreaks that spread across large areas) have dramatically affected population.\n\n### Major Pandemics\n\n| Pandemic | Period | Deaths (estimated) | Impact |\n|----------|--------|-------------------|--------|\n| **The Black Death** | 1346-1353 | 75-200 million | Killed about 1/3 of Europe\'s population |\n| **Spanish Flu** | 1918-1919 | 50-100 million | Killed more people than World War I; spread worldwide |\n| **HIV/AIDS** | 1981-present | ~40 million total | Devastating impact in sub-Saharan Africa |\n| **COVID-19** | 2020-present | ~7 million (official) | Global lockdowns; economic disruption |\n\n### The Spanish Flu\n\n- The Spanish Flu was caused by an **influenza virus**\n- It spread rapidly because of troop movements at the end of World War I\n- It killed **young, healthy adults** — unusual for flu, which normally kills the very young and very old\n- In South Africa, the Spanish Flu killed an estimated **300 000 people** (about 6% of the population at the time)\n- Compare this to World War I, which killed about 9 million soldiers globally\n\n### Lessons From Pandemics\n\n- Pandemics can spread rapidly, especially when people travel and live in crowded conditions\n- **Public health measures** (quarantine, hygiene, vaccines) are essential\n- Poverty and inequality make pandemics worse — the poor are always hardest hit\n- International cooperation is needed to respond effectively'),
  fb(8, 'The Spanish Flu of 1918-1919 killed an estimated ___-100 million people worldwide. In South Africa, it killed approximately ___ people.',
    ['50', '300 000'],
    'The Spanish Flu was one of the deadliest pandemics in human history. It struck just as World War I was ending and spread rapidly through troop movements. In South Africa, it killed about 6% of the population — showing how devastating pandemics can be.'),
  q(9, 'Why are developing countries usually harder hit by pandemics than developed countries?',
    ['They have weaker healthcare systems, less access to clean water and sanitation, and more poverty, which makes disease prevention and treatment harder', 'Developed countries have more diseases', 'Pandemics affect all countries equally', 'Developing countries have fewer people'], 0,
    'Pandemics disproportionately affect developing countries because their healthcare systems are under-resourced, many people lack clean water and sanitation, overcrowded living conditions help diseases spread, and poverty limits access to treatment and vaccines.'),
  t(10, '## Population and the Future\n\nUnderstanding population trends helps us plan for the future and address challenges.\n\n### Global Trends\n\n| Trend | Implication |\n|-------|-------------|\n| **Population still growing** | Need for more food, water, housing, and jobs |\n| **Growth rate slowing** | Birth rates are falling in most countries |\n| **Urbanisation** | More people living in cities; rural areas losing population |\n| **Ageing populations** (developed world) | More elderly people needing care and pensions |\n| **Youth bulge** (developing world) | Many young people needing education and jobs |\n\n### South Africa\'s Population Challenges\n\n- South Africa\'s population is approximately **62 million** (2023)\n- About **30% are under 15** — a young population\n- **Unemployment** (especially youth unemployment, over 60%) is a major crisis\n- **HIV/AIDS** continues to affect millions\n- **Migration** from other African countries adds to urban population growth\n- **Inequality** — South Africa is one of the most unequal countries in the world\n\n### What Can Be Done?\n\n- **Education**: Especially for girls — educated women have fewer children and healthier families\n- **Healthcare**: Continue improving access to healthcare and HIV treatment\n- **Job creation**: Economic growth to provide employment for young people\n- **Family planning**: Access to contraception and reproductive health services\n- **Reducing inequality**: Addressing the gap between rich and poor\n\nPopulation is not just about numbers — it is about **people** and ensuring that everyone has access to a dignified life.'),
];

// =============================================================================
// CHAPTER 7 (History – Term 4): Co-operation and Conflict on the Frontiers
// of the Cape Colony in the Early 19th Century
// =============================================================================

// --- Lesson 1: The Eastern Frontier of European Settlement ---
blockNum = 0;
const ch7_lesson1 = [
  t(1, '## The Eastern Frontier\n\nBy the late 1700s, the Cape Colony\'s **eastern frontier** had become a zone of intense contact, conflict, and co-operation between different groups.\n\n### Peoples of the Eastern Frontier\n\n| Group | Description |\n|-------|-------------|\n| **Xhosa chiefdoms** | Bantu-speaking farmers and cattle herders; well-organised under chiefs; had lived in the region for centuries |\n| **Trekboers** | Dutch-speaking frontier farmers expanding eastward from the Cape |\n| **Khoikhoi** | Indigenous pastoralists; many had lost their land and cattle |\n| **San** | Hunter-gatherers; driven into marginal areas by both Xhosa and settlers |\n| **British settlers** | Arrived from 1820; settled around Grahamstown (Makhanda) |\n\n### The Frontier Wars\n\n- Between **1779 and 1879**, nine major wars were fought on the eastern frontier\n- These are known as the **Cape Frontier Wars** or **Xhosa Wars**\n- The wars were primarily about **land** and **cattle** — both the settlers and the Xhosa depended on cattle herding and farming\n- The **Fish River** was declared the boundary between the colony and the Xhosa, but neither side respected it consistently\n\n### Co-operation and Conflict\n\nRelations on the frontier were complex — not always hostile:\n- **Trade**: Xhosa and settlers traded cattle, tobacco, beads, and metal goods\n- **Labour**: Some Xhosa worked on settler farms\n- **Conflict**: Cattle raids, land disputes, and military campaigns\n- **Diplomacy**: Chiefs and colonial officials negotiated treaties (often broken)'),
  q(2, 'What was the main cause of conflict on the eastern frontier of the Cape Colony?',
    ['Competition for land and cattle between the Xhosa and European settlers', 'Religious differences', 'Language barriers', 'The Xhosa wanted to trade with Europe'], 0,
    'Both the Xhosa and the settlers depended on cattle and farmland. As the colony expanded eastward, it pushed into Xhosa territory. Disputes over land and cattle — including cattle raids by both sides — fuelled a century of frontier wars.'),
  t(3, '## British Immigration and the Arrival of the 1820 Settlers\n\nIn **1820**, approximately **4 000 British settlers** arrived at the eastern frontier of the Cape Colony.\n\n### Why Were They Sent?\n\n| Reason | Explanation |\n|--------|-------------|\n| **Buffer zone** | The British government wanted settlers between the colony and the Xhosa to prevent further frontier wars |\n| **Economic problems in Britain** | The end of the Napoleonic Wars (1815) caused unemployment and poverty in Britain |\n| **Populate the frontier** | More settlers would strengthen British control of the area |\n\n### Where They Settled\n\n- The settlers were placed in the **Zuurveld** (around modern-day Grahamstown/Makhanda and Port Elizabeth/Gqeberha)\n- They were given small plots of land — too small for profitable cattle farming\n- Many settlers were not farmers — they were artisans, tradespeople, and professionals from British cities\n\n### Difficulties Faced\n\n- **Drought, floods, and crop failure** made farming very difficult\n- Small plot sizes were inadequate for the local conditions\n- The **frontier was dangerous** — conflict with Xhosa was ongoing\n- Many settlers gave up farming and moved to towns like **Grahamstown** and **Port Elizabeth**\n\n### Contributions of the 1820 Settlers\n\n- They brought **English language and culture** to the eastern Cape\n- They helped establish **journalism**: The first independent newspaper (*The South African Commercial Advertiser*, 1824)\n- They promoted **English education** and legal traditions\n- They helped develop towns and trade in the eastern Cape'),
  fb(4, 'Approximately ___ British settlers arrived at the Cape in 1820. They were settled in the Zuurveld as a ___ zone between the colony and the Xhosa.',
    ['4 000', 'buffer'],
    'The 1820 settlers were strategically placed on the frontier to serve as a human buffer between the Xhosa and the rest of the colony. However, many were city people with no farming experience, and the small plots and difficult conditions forced many to abandon farming.'),
  t(5, '## Frontier Wars on the Eastern Frontier\n\nThe frontier wars between the Xhosa and the Cape Colony were fought over nearly a century (1779-1879).\n\n### Key Frontier Wars\n\n| War | Date | Key Events |\n|-----|------|------------|\n| **1st War** | 1779-1781 | First major Xhosa-colonial clash over land in the Zuurveld |\n| **4th War** | 1811-1812 | The British expelled thousands of Xhosa west of the Fish River |\n| **5th War** | 1818-1819 | Chief Makhanda (Nxele) attacked Grahamstown but was defeated; imprisoned on Robben Island |\n| **6th War** | 1834-1836 | Xhosa attacked the colony after cattle theft and land loss |\n| **8th War** | 1850-1853 | The "War of Mlanjeni"; fierce Xhosa resistance |\n| **9th War** | 1877-1879 | Final war; the Xhosa were fully conquered |\n\n### Chief Makhanda (Nxele)\n\n- **Makhanda** was a Xhosa prophet and war leader\n- In **1819**, he led approximately **10 000 Xhosa warriors** in an attack on the British garrison at **Grahamstown**\n- The attack nearly succeeded but was eventually repelled with the help of Khoikhoi allies\n- Makhanda surrendered and was imprisoned on **Robben Island**\n- He drowned trying to escape from Robben Island — becoming a symbol of resistance\n- The city of Grahamstown was officially renamed **Makhanda** in his honour in 2018\n\n### The Pattern of the Wars\n\n- Each war resulted in the Xhosa losing **more land**\n- The colonial boundary was pushed further east after each war\n- Xhosa cattle were seized and their crops destroyed\n- By the 1850s, Xhosa society was under severe pressure'),
  q(6, 'Why was Chief Makhanda\'s attack on Grahamstown in 1819 significant?',
    ['He led 10 000 warriors in a bold attack that nearly captured the British garrison, showing the determination of Xhosa resistance', 'He peacefully surrendered to the British', 'He was a British ally', 'The attack was unimportant'], 0,
    'Makhanda\'s attack on Grahamstown was one of the most dramatic moments of the frontier wars. Leading 10 000 warriors against a fortified British garrison showed extraordinary courage. Although the attack ultimately failed, Makhanda became a powerful symbol of resistance.'),
  t(7, '## The Movement of the Trekboers with Their Slaves and Servants\n\nThe expansion of the frontier was driven largely by **trekboers** — Dutch-speaking frontier farmers who moved deeper into the interior.\n\n### The Great Trek (1830s-1840s)\n\n- In the 1830s, approximately **12 000-14 000 Boers** left the Cape Colony and trekked into the interior\n- They became known as **Voortrekkers** ("those who trek forward")\n- They took with them their families, cattle, wagons, and **Khoikhoi servants and enslaved people** (until slavery was abolished in 1834)\n\n### Reasons for the Great Trek\n\n| Reason | Explanation |\n|--------|-------------|\n| **Land shortage** | Trekboers needed more land for cattle farming |\n| **Abolition of slavery (1834)** | Many Boers opposed the British abolition of slavery |\n| **Equal legal status** | Ordinance 50 (1828) gave Khoikhoi people equal legal status — many Boers objected |\n| **Frontier insecurity** | Conflict with the Xhosa made life on the frontier dangerous |\n| **British rule** | Boers resented British interference in their way of life |\n| **Language** | English was imposed as the official language |\n\n### Impact of the Trek\n\n- The Voortrekkers established the **Transvaal (South African Republic)** and the **Orange Free State**\n- They came into conflict with the **Zulu**, **Ndebele**, and **Sotho** peoples whose land they entered\n- The Great Trek is one of the most important events in South African history — it shaped the political geography of the country'),
  fb(8, 'The Boers who left the Cape Colony in the 1830s-1840s were called ___. One major reason for the Great Trek was the British ___ of slavery in 1834.',
    ['Voortrekkers', 'abolition'],
    'The Voortrekkers were Afrikaner frontier farmers who rejected British rule and set out to establish their own independent republics in the interior. The abolition of slavery was a significant factor — many Boers depended on enslaved labour and resented British interference with what they considered their property rights.'),
  q(9, 'How did the Great Trek affect the indigenous peoples whose territories the Voortrekkers entered?',
    ['The Voortrekkers took land from the Zulu, Ndebele, Sotho, and other peoples, leading to conflict and displacement', 'Indigenous peoples welcomed the Voortrekkers', 'The Voortrekkers avoided all indigenous peoples', 'There was no interaction between them'], 0,
    'The Voortrekkers moved into territories already inhabited by African peoples. This led to major conflicts, including the Battle of Blood River (1838) between the Voortrekkers and the Zulu. African communities lost land and were displaced by the advancing settlers.'),
  t(10, '## The Kora and Griqua\n\nThe eastern and northern frontiers of the Cape Colony were home to other important communities who played significant roles in frontier history.\n\n### The Griqua\n\n- The **Griqua** were a mixed-heritage people descended from Khoikhoi, European settlers, and enslaved people\n- They spoke Dutch/Afrikaans and were often Christian\n- Led by chiefs like **Adam Kok** and **Waterboer**, they established communities in the **Northern Cape** and beyond\n- The Griqua were skilled horsemen and gunmen\n- They traded extensively with both African communities and European settlers\n\n### The Kora\n\n- The **Kora** (also spelled Korana) were a Khoikhoi group who lived along the **Orange River**\n- They were cattle herders and traders\n- Like the Griqua, they had access to horses and guns through trade\n- They raided neighbouring communities for cattle and traded with all groups on the frontier\n\n### Missionaries and Traders\n\n- **Missionaries** (like those from the London Missionary Society) established mission stations on the frontier\n- They converted some Khoikhoi, Griqua, and Xhosa people to Christianity\n- They taught literacy and sometimes spoke out against settler abuses\n- However, missionaries also disrupted traditional cultures and sometimes served colonial interests\n- **Traders** operated on the frontier, exchanging European goods (guns, ammunition, cloth, beads) for ivory, cattle, and hides\n\n### Case Study: Robert Moffat (1795-1883)\n\n- Robert Moffat was a Scottish missionary who lived at **Kuruman** in the Northern Cape for over 50 years\n- He translated the Bible into **Setswana** — the first complete Bible in an African language\n- His work influenced the work of **David Livingstone** (who married Moffat\'s daughter)\n- Missionaries like Moffat played a complex role — bringing education and healthcare but also contributing to cultural change and colonial expansion'),
];

// --- Lesson 2: The Northern Frontier and Co-operation Between Groups ---
blockNum = 0;
const ch7_lesson2 = [
  t(1, '## The Northern Frontier of European Settlement\n\nWhile the eastern frontier saw the most dramatic conflicts, the **northern frontier** of the Cape Colony was also a zone of contact between different peoples.\n\n### Peoples of the Northern Frontier\n\n| Group | Area | Economy |\n|-------|------|----------|\n| **Trekboers** | Expanding northward from the Cape | Cattle and sheep farming |\n| **Griqua** | Along the Orange River and beyond | Cattle, trading, hunting |\n| **Kora (Korana)** | Along the Orange River | Cattle herding, raiding, trading |\n| **Tswana chiefdoms** | Northern Cape and beyond | Mixed farming (cattle and crops) |\n| **San** | Mountainous and semi-arid areas | Hunting and gathering |\n| **Missionaries** | Scattered mission stations | Converting and educating local people |\n\n### Trade on the Northern Frontier\n\n| Goods Moving North | Goods Moving South |\n|--------------------|-----------------------|\n| Guns and ammunition | Ivory (elephant tusks) |\n| Horses | Cattle and hides |\n| Cloth and beads | Ostrich feathers |\n| Tobacco and alcohol | Game skins |\n| Metal tools | Labour |\n\nTrade was a major form of **co-operation** between different groups, even when political relations were tense.'),
  q(2, 'Why was trade important on the northern frontier of the Cape Colony?',
    ['It provided a basis for peaceful co-operation between different groups, allowing them to exchange goods they needed', 'Trade was not important on the frontier', 'Only the Griqua traded', 'Trade only happened in Cape Town'], 0,
    'Trade connected trekboers, Griqua, Kora, Tswana, and San communities despite their differences. Each group had goods the others wanted — settlers had guns and cloth, while African communities had ivory, cattle, and other resources. Trade was often the basis for peaceful relations.'),
  t(3, '## The Tswana World and the Southern Borders\n\n### The Tswana\n\n- The **Tswana** people lived in large, well-organised chiefdoms in what is now the **North West Province**, **Northern Cape**, and **Botswana**\n- They were **farmers** who grew sorghum and millet and herded cattle\n- They lived in large **towns** — some Tswana settlements had populations of 10 000-20 000 people\n- Their political system was based on **chiefs** (kgosi) who ruled with the advice of a **council** (pitso)\n\n### Tswana-European Contact\n\n- The first European contact with the Tswana came through **traders** and **missionaries** in the late 1700s and early 1800s\n- The **London Missionary Society** established mission stations among the Tswana\n- Robert Moffat at Kuruman was the most famous missionary among the Tswana\n- Trade brought guns, horses, and European goods into Tswana society\n\n### The Tswana and Ivory Trade\n\n| Aspect | Detail |\n|--------|--------|\n| **What was traded** | Ivory (elephant tusks) was the most valuable trade good |\n| **How it worked** | Tswana hunters killed elephants; traded ivory for European goods |\n| **Impact** | Elephant populations declined; guns changed the balance of power |\n| **Missionaries\' role** | Often acted as intermediaries in trade |\n| **Iron and copper** | Tswana were skilled metalworkers; traded iron and copper goods |'),
  fb(4, 'The Tswana people lived in large, well-organised chiefdoms and their political leader was called a ___. The most valuable trade good on the northern frontier was ___ (elephant tusks).',
    ['kgosi', 'ivory'],
    'The kgosi (chief) governed with the advice of a pitso (council), showing that Tswana political systems were structured and consultative. Ivory was enormously valuable in European markets — a single pair of tusks could buy a gun, which dramatically changed power dynamics on the frontier.'),
  t(5, '## Co-operation and Conflict Between Groups\n\nLife on the frontier involved both **co-operation** (working together) and **conflict** (fighting) between different groups.\n\n### Forms of Co-operation\n\n| Type | Example |\n|------|----------|\n| **Trade** | Exchanging goods — guns for ivory, cattle for cloth |\n| **Intermarriage** | Some Griqua, Khoikhoi, and Europeans married, creating mixed communities |\n| **Military alliances** | Groups sometimes allied against common enemies |\n| **Mission stations** | Missionaries provided education, healthcare, and a meeting point for different groups |\n| **Labour** | Khoikhoi and others worked on settler farms in exchange for food, shelter, and wages |\n\n### Forms of Conflict\n\n| Type | Example |\n|------|----------|\n| **Land disputes** | Settlers and indigenous peoples competed for the best land and water |\n| **Cattle raiding** | All groups raided each other\'s cattle |\n| **Wars** | Frontier wars between settlers and Xhosa; commandos against San |\n| **Resistance** | Enslaved people and servants resisted through escape and sabotage |\n| **Displacement** | Stronger groups pushed weaker groups off their land |\n\n### The Complexity of Frontier Life\n\n- Frontier life was **not simply** black vs white or coloniser vs colonised\n- Alliances shifted — Khoikhoi sometimes fought alongside the British against the Xhosa\n- The Griqua traded with everyone and allied with whoever suited their interests\n- Within each group, there were different factions and opinions\n- Understanding this complexity is essential for understanding South African history'),
  q(6, 'Why is it important to understand that frontier life involved both co-operation and conflict?',
    ['Because the reality was complex — different groups sometimes traded and allied together, and sometimes fought each other, depending on circumstances', 'Because only conflict happened on the frontier', 'Because there was only co-operation', 'Because it does not matter'], 0,
    'History is rarely simply about heroes and villains. On the Cape frontier, the same groups that traded peacefully could fight violently when circumstances changed. Understanding this complexity helps us avoid oversimplified narratives and appreciate the full picture of South African history.'),
  t(7, '## The Impact of Colonisation on Indigenous Peoples\n\nBy the mid-1800s, European colonisation had profoundly changed the lives of indigenous peoples in the Cape and beyond.\n\n### Land Dispossession\n\n- The Khoikhoi lost virtually all their land and cattle\n- The San were hunted and driven into marginal areas\n- The Xhosa were progressively pushed east of the Kei River\n- Land dispossession was the **foundation** of colonial power — without land, indigenous peoples could not sustain themselves\n\n### Labour Exploitation\n\n- Dispossessed Khoikhoi were forced to work on settler farms\n- Enslaved people did much of the colony\'s heavy labour\n- After the abolition of slavery in 1834, the **Masters and Servants Ordinance** (1841) kept former slaves and Khoikhoi in conditions close to slavery\n- Labour exploitation benefited the colonial economy at the expense of indigenous peoples\n\n### Cultural Change\n\n| Aspect | Impact |\n|--------|--------|\n| **Language** | Dutch/Afrikaans and English replaced indigenous languages in many areas |\n| **Religion** | Christianity replaced traditional beliefs for many (through mission stations) |\n| **Social structure** | Traditional leadership systems were undermined |\n| **Education** | Mission education taught European values and skills |\n| **Law** | European legal systems replaced traditional justice |\n\n### Resistance and Survival\n\nDespite all these pressures, indigenous peoples **survived and adapted**:\n- The Xhosa maintained their language, culture, and identity despite military defeat\n- Islam survived and flourished among formerly enslaved communities\n- Khoikhoi descendants contributed to the formation of the Coloured community\n- Indigenous knowledge systems (medicine, agriculture, environment) were preserved through oral tradition'),
  fb(8, 'Land ___ was the foundation of colonial power because without land, indigenous peoples could not sustain themselves. After slavery was abolished in 1834, the Masters and ___ Ordinance kept former slaves in exploitative conditions.',
    ['dispossession', 'Servants'],
    'Land dispossession forced indigenous peoples into dependence on the colonial economy for survival. The Masters and Servants Ordinance of 1841 effectively replaced slavery with a system of forced labour, showing that legal abolition did not automatically bring freedom and equality.'),
  q(9, 'How did the Xhosa people respond to colonisation?',
    ['They resisted through nine frontier wars spanning nearly a century, maintaining their culture and identity despite eventual military defeat', 'They immediately accepted colonial rule', 'They moved to Europe', 'They had no response to colonisation'], 0,
    'The Xhosa fought one of the longest resistance campaigns in African history — nine frontier wars from 1779 to 1879. Even after military defeat, they preserved their language (isiXhosa), customs, and identity. This resilience is a central theme of South African history.'),
  t(10, '## Looking Back: Key Themes of Grade 7 History\n\nThe history topics studied in Grade 7 share important themes that connect them together.\n\n### Theme 1: Trade and Exchange\n\n- Trans-Saharan trade built the kingdoms of Mali and Timbuktu\n- The triangular trade connected Europe, Africa, and the Americas\n- Trade on the Cape frontier involved guns, ivory, cattle, and cloth\n- Trade shaped power relations — those who controlled trade gained wealth and power\n\n### Theme 2: Colonisation and Its Consequences\n\n- The transatlantic slave trade was a form of economic colonisation — exploiting Africa for profit\n- The Dutch and then the British colonised the Cape\n- Colonisation meant land dispossession, forced labour, and cultural disruption for indigenous peoples\n- The patterns established during colonisation (inequality, racial hierarchy) still affect South Africa today\n\n### Theme 3: Resistance\n\n- Enslaved people resisted through rebellion, escape, and cultural preservation\n- The Khoikhoi fought two wars against the Dutch\n- The Xhosa fought nine frontier wars\n- The San used guerrilla tactics against settler expansion\n- Resistance showed that colonised peoples never passively accepted their oppression\n\n### Theme 4: Connections\n\n- The wealth from slavery funded the Industrial Revolution (Grade 8 topic)\n- The frontiers of the Cape Colony set the stage for the Great Trek and the Boer republics\n- The Cape Colony\'s racial policies foreshadowed apartheid\n- Understanding Grade 7 History is essential for understanding the history you will study in Grade 8 and beyond'),
];

// =============================================================================
// CHAPTER 8 (Geography – Term 4): Natural Resources and Conservation in
// South Africa
// =============================================================================

// --- Lesson 1: Natural Resources and Management ---
blockNum = 0;
const ch8_lesson1 = [
  t(1, '## What Are Natural Resources?\n\nA **natural resource** is anything from nature that people use to meet their needs. Natural resources include water, soil, air, minerals, forests, and wildlife.\n\n### Types of Natural Resources\n\n| Type | Definition | Examples |\n|------|-----------|----------|\n| **Renewable** | Can be replaced or regrown within a human lifetime | Water, soil, forests, wind, solar energy, fish |\n| **Non-renewable** | Cannot be replaced once used up (take millions of years to form) | Coal, oil, natural gas, gold, diamonds, iron ore |\n\n### Natural Resources on Earth\n\n| Resource | Use |\n|----------|------|\n| **Water** | Drinking, farming, industry, energy (hydroelectric) |\n| **Air** | Breathing, wind energy |\n| **Soil** | Growing food, building materials |\n| **Minerals** | Manufacturing, construction, technology |\n| **Forests** | Timber, paper, fuel, oxygen production |\n| **Wildlife** | Food, tourism, ecological balance |\n| **Fossil fuels** | Energy (coal, oil, natural gas) |\n\n### Use and Abuse of Natural Resources\n\n- **Use**: Taking resources responsibly, ensuring they last for future generations\n- **Abuse**: Overusing or wasting resources, causing damage to the environment\n- Examples of abuse: deforestation, overfishing, pollution of rivers, soil erosion from overgrazing\n\n### Sustainability\n\n**Sustainable use** means using resources in a way that meets today\'s needs without preventing future generations from meeting their needs. This is one of the most important concepts in Geography.'),
  q(2, 'What is the difference between renewable and non-renewable resources?',
    ['Renewable resources can be replaced within a human lifetime (like forests and water), while non-renewable resources take millions of years to form and cannot be replaced once used (like coal and gold)', 'All resources are renewable', 'There is no difference', 'Non-renewable resources grow back faster'], 0,
    'The distinction is crucial for sustainability. Renewable resources (water, forests, fish) can regenerate, but only if we do not use them faster than they can recover. Non-renewable resources (minerals, fossil fuels) exist in limited quantities — once used, they are gone forever.'),
  t(3, '## Conservation — Why and How\n\n**Conservation** means the careful management and protection of natural resources to prevent waste, destruction, and overuse.\n\n### Why Conserve Resources?\n\n| Reason | Explanation |\n|--------|-------------|\n| **Limited supply** | Many resources (especially non-renewable ones) are running out |\n| **Ecosystem health** | Healthy ecosystems provide clean air, water, and food |\n| **Future generations** | We have a responsibility to leave resources for those who come after us |\n| **Biodiversity** | Protecting habitats preserves the variety of life on Earth |\n| **Economic value** | Natural resources drive the economy — destroying them hurts everyone |\n| **Climate change** | Burning fossil fuels causes global warming; conservation reduces emissions |\n\n### Reasons for Conservation — Including Marine Reserves\n\n- **Marine reserves** protect ocean ecosystems from overfishing and pollution\n- South Africa has several marine protected areas, including **iSimangaliso Wetland Park** and **Table Mountain National Park** marine section\n- Marine reserves allow fish populations to recover and protect coral reefs and kelp forests\n- They also support the **fishing industry** by ensuring fish stocks are sustainable\n\n### Conservation Methods\n\n| Method | How It Works |\n|--------|---------------|\n| **National parks and reserves** | Protecting areas of natural habitat |\n| **Legislation** | Laws that protect endangered species and limit pollution |\n| **Sustainable farming** | Farming methods that protect soil and water |\n| **Recycling** | Reusing materials to reduce waste and resource extraction |\n| **Renewable energy** | Using wind and solar instead of coal |\n| **Community conservation** | Local communities managing their own natural resources |'),
  fb(4, 'Conservation means the careful management and ___ of natural resources. Marine ___ protect ocean ecosystems and allow fish populations to recover.',
    ['protection', 'reserves'],
    'Conservation is not about never using resources — it is about using them wisely and sustainably. Marine reserves are particularly important in South Africa, where the ocean provides food, employment (fishing industry), and tourism (whale watching, diving).'),
  t(5, '## Conservation Areas in South Africa — Purpose and Location\n\nSouth Africa has an extensive system of conservation areas that protect its remarkable biodiversity.\n\n### Types of Conservation Areas\n\n| Type | Purpose | Example |\n|------|---------|----------|\n| **National parks** | Protect large ecosystems; managed by SANParks | Kruger, Table Mountain, Addo Elephant |\n| **Nature reserves** | Protect specific habitats or species; provincial management | Hluhluwe-iMfolozi, Cape Nature reserves |\n| **Marine protected areas** | Protect ocean ecosystems | iSimangaliso, Tsitsikamma |\n| **World Heritage Sites** | Internationally recognised areas of outstanding value | Robben Island, Cradle of Humankind, Cape Floral Region |\n| **Biosphere reserves** | Balance conservation with sustainable development | Waterberg, Kogelberg |\n| **Community conservancies** | Managed by local communities | Various in KZN and Eastern Cape |\n\n### South Africa\'s Major National Parks\n\n| Park | Province | Key Features |\n|------|----------|--------------|\n| **Kruger** | Limpopo, Mpumalanga | Largest park; Big Five; nearly 2 million hectares |\n| **Table Mountain** | Western Cape | Iconic mountain; fynbos vegetation; one of the New7Wonders of Nature |\n| **Addo Elephant** | Eastern Cape | Over 600 elephants; expanding to include marine area |\n| **Garden Route** | Western/Eastern Cape | Forests, lakes, and coastal scenery |\n| **Kgalagadi** | Northern Cape | Transfrontier park shared with Botswana; desert wildlife |'),
  q(6, 'Why does South Africa invest in national parks and conservation areas?',
    ['To protect biodiversity, support tourism and the economy, preserve natural heritage, and ensure resources for future generations', 'Only for tourist entertainment', 'Because there is too much unused land', 'National parks serve no important purpose'], 0,
    'Conservation areas serve multiple vital purposes. They protect South Africa\'s extraordinary biodiversity (third most biodiverse country in the world), support a tourism industry worth billions of rands, preserve natural heritage, and protect ecosystem services like clean water and air.'),
  t(7, '## Eco-Tourism — Examples\n\n**Eco-tourism** is tourism that focuses on visiting natural areas while minimising environmental impact and benefiting local communities.\n\n### Principles of Eco-Tourism\n\n| Principle | Explanation |\n|-----------|-------------|\n| **Minimise impact** | Reduce damage to the environment (small groups, stay on paths) |\n| **Build awareness** | Educate tourists about nature and conservation |\n| **Benefit locals** | Money from tourism should go to local communities |\n| **Conserve** | Tourism income helps fund conservation efforts |\n| **Respect culture** | Respect local customs and traditions |\n\n### Examples of Eco-Tourism in South Africa\n\n| Example | Location | Activities |\n|---------|----------|------------|\n| **Whale watching** | Hermanus, Western Cape | Watching Southern Right Whales from the shore (June-November) |\n| **Shark cage diving** | Gansbaai, Western Cape | Observing Great White Sharks in their natural habitat |\n| **Kruger National Park** | Limpopo/Mpumalanga | Game drives, bush walks, bird watching |\n| **iSimangaliso Wetland Park** | KwaZulu-Natal | Snorkelling, turtle tours, hippo and crocodile boat trips |\n| **Community conservation** | Various | Staying in community-owned lodges; guided cultural tours |\n\n### Benefits of Eco-Tourism\n\n- Creates **jobs** in rural areas where unemployment is high\n- Provides **income** for conservation (park entrance fees, accommodation fees)\n- Encourages communities to **protect** natural resources rather than exploit them\n- Promotes **cultural exchange** between tourists and local communities\n- South Africa\'s eco-tourism industry is worth **billions of rands** annually'),
  fb(8, 'Eco-tourism focuses on visiting natural areas while minimising environmental ___. One of the principles of eco-tourism is that money from tourism should benefit ___ communities.',
    ['impact', 'local'],
    'Eco-tourism is different from mass tourism because it prioritises environmental protection and community benefit over profit. In South Africa, eco-tourism can transform conservation from a cost into an economic benefit — giving communities a financial reason to protect their natural heritage.'),
  q(9, 'How does eco-tourism help conservation?',
    ['It provides income to fund conservation, gives local communities a financial reason to protect nature, and raises awareness about environmental issues', 'Eco-tourism damages the environment', 'It only benefits foreign tourists', 'Eco-tourism and conservation are unrelated'], 0,
    'Eco-tourism creates a positive cycle: tourists pay to visit natural areas, the money funds conservation and creates local jobs, and communities that benefit from tourism are motivated to protect the environment. This approach helps conservation pay for itself.'),
  t(10, '## Community Conservation Projects\n\nCommunity conservation involves **local people** taking an active role in managing and protecting their natural resources.\n\n### Why Community Conservation?\n\n- Local communities **know their environment** best\n- Conservation is more successful when communities **benefit directly**\n- Top-down conservation (imposed by government) often fails because communities feel excluded\n- Community conservation empowers people to make decisions about their own resources\n\n### Examples in South Africa\n\n| Project | Location | What It Does |\n|---------|----------|---------------|\n| **Working for Water** | Nationwide | Employs local people to remove alien invasive plants that threaten water supplies |\n| **Working for Wetlands** | Nationwide | Restores and protects wetlands that filter water and prevent flooding |\n| **Community game reserves** | KZN, Eastern Cape | Communities manage game reserves and share tourism income |\n| **Spekboomveld restoration** | Eastern Cape | Planting spekboom (a carbon-absorbing plant) to restore degraded land |\n| **Coastal clean-ups** | All coastal provinces | Communities organise beach and river clean-ups |\n\n### The Working for Water Programme\n\n- One of South Africa\'s most successful conservation programmes\n- **Alien invasive plants** (like black wattle, eucalyptus, and Port Jackson willow) use huge amounts of water\n- Removing them **increases water availability** — crucial in water-scarce South Africa\n- The programme creates **thousands of jobs** for unemployed people\n- It is a model of how conservation, job creation, and water management can work together\n\n### Your Role in Conservation\n\n- Save water at home and school\n- Do not litter — especially near rivers and the coast\n- Recycle paper, glass, plastic, and metal\n- Plant indigenous trees and gardens\n- Report environmental damage (pollution, illegal dumping)\n- Learn about your local environment and share your knowledge'),
];

// --- Lesson 2: Water in South Africa ---
blockNum = 0;
const ch8_lesson2 = [
  t(1, '## Water in South Africa\n\nWater is South Africa\'s most **precious natural resource**. The country is classified as **water-scarce** — we receive less rainfall than the world average.\n\n### South Africa\'s Water Situation\n\n| Fact | Detail |\n|------|--------|\n| **Average rainfall** | About 500 mm per year (world average is 860 mm) |\n| **Rainfall distribution** | Very uneven — the east is wet, the west is dry |\n| **Evaporation** | High evaporation due to warm temperatures reduces available water |\n| **River systems** | Many rivers are seasonal (only flow after rain) |\n| **Groundwater** | Limited groundwater reserves in most areas |\n| **Growing demand** | Population growth, urbanisation, and industry increase demand |\n\n### Who Uses South Africa\'s Water?\n\n| Sector | Approximate Percentage |\n|--------|------------------------|\n| **Agriculture (irrigation)** | 60% |\n| **Urban and domestic** | 27% |\n| **Industry and mining** | 8% |\n| **Forestry** | 3% |\n| **Other (environment, livestock)** | 2% |\n\n### Sources of Water\n\n- **Dams**: South Africa has over 5 000 registered dams that store water for use during dry periods\n- **Rivers**: Major rivers include the Orange, Vaal, Limpopo, and Tugela\n- **Groundwater**: Boreholes tap underground water — important in rural and dry areas\n- **Inter-basin transfers**: Water is moved from areas of surplus to areas of shortage (e.g., the Lesotho Highlands Water Project supplies water to Gauteng)'),
  q(2, 'Why is South Africa classified as a water-scarce country?',
    ['South Africa receives less rainfall than the world average, rainfall is unevenly distributed, and high evaporation reduces the water available for use', 'South Africa has too many rivers', 'It rains every day in South Africa', 'South Africa has more water than it needs'], 0,
    'South Africa\'s average rainfall (500 mm/year) is well below the world average (860 mm/year). Much of the country is semi-arid, and high temperatures cause significant evaporation. Combined with growing demand from population growth and industry, this makes water one of South Africa\'s most critical challenges.'),
  t(3, '## Water Availability and Requirements\n\n### Uneven Distribution\n\nSouth Africa\'s rainfall varies dramatically across the country:\n\n| Region | Annual Rainfall | Water Availability |\n|--------|-----------------|--------------------|\n| **KwaZulu-Natal east coast** | 1 000-1 200 mm | Good water supply |\n| **Mpumalanga lowveld** | 600-1 000 mm | Moderate |\n| **Gauteng** | 500-700 mm | Low (but highest demand) |\n| **Northern Cape/Karoo** | 100-300 mm | Very low |\n| **Western Cape** | 500-600 mm (winter rain) | Moderate (seasonal scarcity) |\n\n### The Problem: Supply vs Demand\n\n- **Gauteng** has the highest **demand** for water (most people, most industry) but receives only moderate rainfall\n- The **Lesotho Highlands Water Project** transfers water from Lesotho\'s mountains to the Vaal Dam, which supplies Gauteng\n- The **Western Cape** experienced a severe drought in **2017-2018** when Cape Town nearly ran out of water ("Day Zero")\n\n### Water Requirements by Sector\n\n- **Agriculture**: The largest user — irrigation for crops like maize, wheat, sugarcane, and fruit\n- **Municipalities**: Providing clean water to homes, schools, and businesses\n- **Industry**: Factories, power stations, and mines use large amounts of water\n- **The environment**: Rivers, wetlands, and ecosystems need water to survive — this is called the **ecological reserve**'),
  fb(4, 'The Lesotho Highlands Water Project transfers water from ___\'s mountains to supply Gauteng. In 2017-2018, ___ nearly ran out of water during a severe drought.',
    ['Lesotho', 'Cape Town'],
    'The Lesotho Highlands Water Project is one of the largest water transfer schemes in Africa, essential for keeping Gauteng — South Africa\'s economic heartland — supplied with water. The Cape Town "Day Zero" crisis showed how vulnerable South African cities are to drought.'),
  t(5, '## River Health and Catchment Areas\n\n### What Is a Catchment Area?\n\n- A **catchment area** (also called a watershed or drainage basin) is the area of land that collects rainfall and channels it into a river system\n- Rainwater flows downhill through streams and tributaries into the main river\n- The boundary of a catchment area follows the highest ground (ridges and mountain tops)\n- What happens in a catchment area affects the **quality and quantity** of water in the river\n\n### South Africa\'s Major Catchment Areas\n\n| River System | Catchment Area |\n|-------------|------------------|\n| **Orange-Vaal** | The largest — covers most of the central interior |\n| **Limpopo** | Northern South Africa; shared with Botswana, Zimbabwe, and Mozambique |\n| **Tugela** | KwaZulu-Natal |\n| **Breede** | Western Cape |\n| **Olifants** | Mpumalanga and Limpopo |\n\n### River Health\n\n- Many South African rivers are **polluted** or in poor health\n- Causes of poor river health:\n  - **Sewage**: Raw or poorly treated sewage entering rivers\n  - **Mining**: Acid mine drainage contaminates water\n  - **Agriculture**: Fertilisers and pesticides wash into rivers\n  - **Industry**: Factory waste and chemicals\n  - **Litter**: Plastic and other waste clogs rivers\n  - **Alien plants**: Invasive trees along river banks use excessive water\n\n### Caring for Our Catchment Areas\n\n- Do not dump waste or litter near rivers\n- Maintain riparian (riverbank) vegetation\n- Report pollution to authorities\n- Support the Working for Water programme'),
  q(6, 'What is a catchment area and why is it important?',
    ['A catchment area is the land that collects rainfall and channels it into a river — whatever happens in the catchment (pollution, deforestation) directly affects the river\'s water quality and quantity', 'A catchment area is a type of dam', 'It is where fish are caught', 'Catchment areas are only found in cities'], 0,
    'Understanding catchment areas is essential for water management. If upstream activities pollute the catchment (mining, sewage, farming chemicals), the pollution flows downstream and affects everyone who depends on that river. Protecting catchments means protecting water supply.'),
  t(7, '## Saving Water\n\nIn a water-scarce country like South Africa, every person has a responsibility to use water wisely.\n\n### Water-Saving Tips\n\n| Action | Water Saved |\n|--------|-------------|\n| **Fix leaking taps** | A dripping tap wastes up to 30 litres per day |\n| **Short showers** (2 minutes) | Saves 100+ litres compared to a bath |\n| **Turn off tap while brushing teeth** | Saves 6-8 litres per minute |\n| **Full washing machine loads** | Uses less water per item than multiple small loads |\n| **Water-wise gardening** | Indigenous plants need less water than exotic species |\n| **Rainwater harvesting** | Collecting rainwater in tanks for garden use |\n| **Grey water recycling** | Reusing bath and washing water for gardens |\n| **Dual-flush toilets** | Use less water per flush |\n\n### Water Saving at School\n\n- Report leaking taps and toilets to staff\n- Use water fountains responsibly\n- Do not leave taps running\n- Participate in water-awareness campaigns\n- Design water-saving posters for your school\n\n### The Human Right to Water\n\n- South Africa\'s **Constitution** (Section 27) guarantees the right to access sufficient water\n- The government provides **free basic water** (6 000 litres per household per month — about 25 litres per person per day)\n- Despite this, millions of South Africans still lack reliable access to clean water\n- Water inequality is a serious issue — some communities have abundant water while others have none'),
  fb(8, 'South Africa\'s Constitution guarantees the right to access sufficient ___. A dripping tap can waste up to ___ litres of water per day.',
    ['water', '30'],
    'The constitutional right to water reflects how precious this resource is. Even small actions — like fixing a dripping tap — make a difference when multiplied across millions of households. Water conservation is everyone\'s responsibility.'),
  q(9, 'Why is rainwater harvesting a good strategy for South Africa?',
    ['It captures free water during rainy periods for use during dry periods, reducing demand on municipal water supplies and dams', 'It is illegal in South Africa', 'There is too much rain to harvest', 'Only farmers can harvest rainwater'], 0,
    'Rainwater harvesting is simple and effective — a household tank can collect thousands of litres from a roof during a single rainstorm. This water can be used for gardens, washing, and even drinking (with proper filtration). It reduces pressure on dams and municipal supplies.'),
  t(10, '## Water and the Future\n\nSouth Africa faces growing water challenges that require urgent action.\n\n### Future Challenges\n\n| Challenge | Explanation |\n|-----------|-------------|\n| **Population growth** | More people = more water demand |\n| **Climate change** | Changing rainfall patterns; more droughts in some regions |\n| **Ageing infrastructure** | Old pipes and water treatment plants need replacement |\n| **Pollution** | Mining, industry, and sewage continue to pollute water sources |\n| **Inequality** | Many rural areas and informal settlements lack clean water |\n| **Agriculture** | Farmers need more water but supplies are shrinking |\n\n### Solutions\n\n| Solution | How It Helps |\n|----------|---------------|\n| **Water recycling** | Treating and reusing wastewater |\n| **Desalination** | Removing salt from seawater (expensive but becoming more affordable) |\n| **Better infrastructure** | Fixing leaks in municipal water systems (some cities lose 30-40% of water to leaks) |\n| **Groundwater exploration** | Finding and sustainably using underground water |\n| **Demand management** | Reducing waste through pricing, regulations, and education |\n| **Catchment management** | Protecting water sources through conservation |\n\n### The Bigger Picture\n\n- Water scarcity is a **global** issue — not just a South African problem\n- Countries are learning to share water resources (transboundary rivers like the Orange-Senqu and Limpopo)\n- Technology (desalination, water recycling, smart metering) is improving\n- But ultimately, **every person** must understand that water is precious and use it responsibly\n\n**Water is life.** In South Africa, this is not just a saying — it is a daily reality. Understanding water — where it comes from, how we use it, and how to protect it — is essential for every South African citizen.'),
];

